INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('748bda90-84cd-452b-8cff-25d9185bab43'::uuid, 'card_description', 'A stoa to Zeus Eleutherios built around 425 BC—a rare cult center rather than a marketplace. It was founded to celebrate freedom after the Persian War.', 'In the Ancient Agora of Athens stood the Stoa of Zeus, dedicated to Zeus Eleutherios, a cult founded after the Persian War. Researchers think Mnesikles may have built it.', 'teaser-card-s024:748bda90-84cd-452b-8cff-25d9185bab43:card_description', 'teaser-card-s024 (teaser-card): teaser card, 170 characters, checked PASS, web-verified VERIFIED', '67c8ffb8f5b97b151eab81bdaa8c73948cd78cd40052d643193a3a85f69aaeb1|8917f86577d688e5541e638137ab19dc0034ae563516fd618d7c42361d71154e|8917f86577d688e5541e638137ab19dc0034ae563516fd618d7c42361d71154e', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In the Ancient Agora of Athens stood the Stoa of Zeus, dedicated to Zeus Eleutherios, a cult founded after the Persian War. Researchers think Mnesikles may have built it."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Stoa of Zeus stood in the Ancient Agora of Athens [S1]; it was dedicated to Zeus Eleutherios [S2]; the cult of Zeus Eleutherios was founded after the Persian War [S2]; researchers think Mnesikles may have built it [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-040 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Stoa of Zeus stood in the Ancient Agora of Athens [SUPPORTED: https://en.wikipedia.org/wiki/Stoa_of_Zeus]; It was dedicated to Zeus Eleutherios [SUPPORTED: https://en.wikipedia.org/wiki/Stoa_of_Zeus]; The cult of Zeus Eleutherios was founded after the Persian War [SUPPORTED: https://en.wikipedia.org/wiki/Stoa_of_Zeus]; Researchers think Mnesikles may have built it [SUPPORTED: https://en.wikipedia.org/wiki/Stoa_of_Zeus]"}]'::jsonb),
    ('74e4bdc2-675e-42b9-b390-898eabed0224'::uuid, 'card_description', 'Rising 109 meters above North Somerset, its western end juts as a peninsula into the Bristol Channel. The western cliffs made ramparts unnecessary on that side — only the eastern approach is defended.', 'The wooded ridge of Worlebury Hill carries stone-built ramparts. Excavated in the nineteenth century, it gave up structural details of several storage pits and of the ramparts.', 'teaser-card-s024:74e4bdc2-675e-42b9-b390-898eabed0224:card_description', 'teaser-card-s024 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', 'b790d314cd0e5fb66897d2e90c3e2a716fd6d977eb1affa547e283c8f896ea53|549f2c09efb1b4011fb3461cdab831ceb8505fd59f06b700c4aacc4461660d2d|549f2c09efb1b4011fb3461cdab831ceb8505fd59f06b700c4aacc4461660d2d', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The wooded ridge of Worlebury Hill carries stone-built ramparts. Excavated in the nineteenth century, it gave up structural details of several storage pits and of the ramparts."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Worlebury Hill has a wooded ridge [S2]; it carries stone-built ramparts [S3]; it was excavated in the nineteenth century [S4]; the excavation found structural details of several storage pits [S4]; the excavation found structural details of the ramparts [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify2-003 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Worlebury Hill carries a hillfort (the central claim: a fortified hilltop site) [SUPPORTED: https://en.wikipedia.org/wiki/Worlebury_Camp]; The ridge is wooded [SUPPORTED: https://en.wikipedia.org/wiki/Worlebury_Camp]; The fort has stone-built ramparts [SUPPORTED: https://en.wikipedia.org/wiki/Worlebury_Camp]; It was excavated in the nineteenth century [SUPPORTED: https://en.wikipedia.org/wiki/Worlebury_Camp]; The excavation yielded structural details of several storage pits [SUPPORTED: https://en.wikipedia.org/wiki/Worlebury_Camp]; The excavation yielded structural details of the ramparts [SUPPORTED: https://en.wikipedia.org/wiki/Worlebury_Camp]"}]'::jsonb),
    ('753c8b27-50ac-4659-9d58-dd441ced2936'::uuid, 'card_description', 'Llwynda-Ddu Camp, also known as Llwynda-Ddu Hillfort, is a small Iron Age earthwork in Pentyrch.', 'The egg-shaped Iron Age hillfort of Llwynda-Ddu Camp sits on a small hill in Pentyrch, Cardiff, the ground falling sharply on all sides but the east. A straight causeway leads in.', 'teaser-card-s024:753c8b27-50ac-4659-9d58-dd441ced2936:card_description', 'teaser-card-s024 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', 'a4ad8a46c3228f2dc5582f1d6fcd6bd460ad25e7c059127b6af9d166f559f716|8ecd924a28a5f77c7ce61ed25d72227682117d20442e44f49f64bb3fedd45ed5|8ecd924a28a5f77c7ce61ed25d72227682117d20442e44f49f64bb3fedd45ed5', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The egg-shaped Iron Age hillfort of Llwynda-Ddu Camp sits on a small hill in Pentyrch, Cardiff, the ground falling sharply on all sides but the east. A straight causeway leads in."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Llwynda-Ddu Camp is egg-shaped [S3]; it is an Iron Age hillfort [S1, S2]; it sits on a small hill [S3]; it is in Pentyrch, Cardiff [S1]; the ground falls sharply on all sides except the east [S4]; a straight causeway forms the entrance [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-041 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Llwynda-Ddu Camp is an Iron Age hillfort in Pentyrch, Cardiff [SUPPORTED: https://en.wikipedia.org/wiki/Llwynda-Ddu_Camp]; The site is Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Llwynda-Ddu_Camp]; The site is a hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Llwynda-Ddu_Camp]; It is egg-shaped [SUPPORTED: https://en.wikipedia.org/wiki/Llwynda-Ddu_Camp]; It sits on a small hill [SUPPORTED: https://en.wikipedia.org/wiki/Llwynda-Ddu_Camp]; The ground falls sharply on all sides but the east [SUPPORTED: https://en.wikipedia.org/wiki/Llwynda-Ddu_Camp]; A straight causeway leads in [SUPPORTED: https://en.wikipedia.org/wiki/Llwynda-Ddu_Camp]"}]'::jsonb),
    ('75fdb2b2-7afa-4aa3-874c-71d3b79068dd'::uuid, 'card_description', 'A Roman trading post founded around 40 AD on a lakeshore. It grew into the most significant Gallo-Roman settlement in its canton, complete with temples and workshops.', 'On the eastern shore of Lake Zurich lie the remains of Centum Prata, a Roman vicus where, after a devastating fire, stone buildings with courtyards were erected around 120 AD.', 'teaser-card-s024:75fdb2b2-7afa-4aa3-874c-71d3b79068dd:card_description', 'teaser-card-s024 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', '337f9afe68e8c34824f6fffdb6c9c87d41eb3469470cf69295623da11b2fb720|92b7094602ccb14ba4ad69b8e3657eeea94e5e09358515d8573fec79f572278c|92b7094602ccb14ba4ad69b8e3657eeea94e5e09358515d8573fec79f572278c', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On the eastern shore of Lake Zurich lie the remains of Centum Prata, a Roman vicus where, after a devastating fire, stone buildings with courtyards were erected around 120 AD."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the remains of Centum Prata lie on the eastern shore of Lake Zurich [S1]; Centum Prata was a Roman vicus [S1]; there was a devastating fire [S4]; after the fire, stone buildings with courtyards were erected [S4]; this happened around 120 AD [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-041 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Centum Prata is a Roman vicus [SUPPORTED: https://en.wikipedia.org/wiki/Centum_Prata]; It is Roman and its remains survive [SUPPORTED: https://en.wikipedia.org/wiki/Centum_Prata]; It lies on the eastern shore of Lake Zurich, in Switzerland [SUPPORTED: https://en.wikipedia.org/wiki/Centum_Prata]; A devastating fire struck the village centre before the rebuilding [SUPPORTED: https://en.wikipedia.org/wiki/Centum_Prata]; Stone buildings with courtyards were erected [SUPPORTED: https://en.wikipedia.org/wiki/Centum_Prata]; The rebuilding dates to around 120 AD [SUPPORTED: https://en.wikipedia.org/wiki/Centum_Prata]"}]'::jsonb),
    ('7661e2ac-0a20-46be-9069-961b36db4ac7'::uuid, 'card_description', 'After the fall of the Western Roman Empire, the amphitheatre gradually lost its original function and was used for various purposes, including as a fortress, quarry, and pasture ground.', 'Built from local limestone, the Pula Arena once held up to 23,000 spectators for gladiatorial contests and animal hunts, with subterranean passages to manage performers and animals.', 'teaser-card-s024:7661e2ac-0a20-46be-9069-961b36db4ac7:card_description', 'teaser-card-s024 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '9304d09cd4aea678dd122644cc5d863ce13dcb8af0d668a6fbe679bec8da61a1|4ad05ef20c59f204fd45019bbaaf2601600562d5a03a07712fb346509a545b35|4ad05ef20c59f204fd45019bbaaf2601600562d5a03a07712fb346509a545b35', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Built from local limestone, the Pula Arena once held up to 23,000 spectators for gladiatorial contests and animal hunts, with subterranean passages to manage performers and animals."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Pula Arena is built from local limestone [S3]; it once held up to 23,000 spectators [S2]; it hosted gladiatorial contests [S2]; it hosted animal hunts [S2]; it has subterranean passages [S4]; the passages were used to manage performers and animals [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-041 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Pula Arena is a Roman amphitheatre in Pula, Croatia [SUPPORTED: https://en.wikipedia.org/wiki/Pula_Arena]; It is in Pula [SUPPORTED: https://en.wikipedia.org/wiki/Pula_Arena]; It is built from local limestone [SUPPORTED: https://en.wikipedia.org/wiki/Pula_Arena]; It once held up to 23,000 spectators [SUPPORTED: https://en.wikipedia.org/wiki/Pula_Arena]; It was a venue for gladiatorial contests [SUPPORTED: https://en.wikipedia.org/wiki/Pula_Arena]; It was a venue for animal hunts [SUPPORTED: https://en.wikipedia.org/wiki/Pula_Arena]; Subterranean passages managed performers and animals [SUPPORTED: https://en.wikipedia.org/wiki/Pula_Arena]"}]'::jsonb),
    ('76c51ba8-fb3f-4a54-9cc2-8f6feafa9594'::uuid, 'card_description', NULL, 'Dedicated in AD 32 to the god Bel, the Templo de Bel in Palmyra stood on a tell where human occupation goes back to the third millennium BC, and later became a Christian church.', 'teaser-card-s024:76c51ba8-fb3f-4a54-9cc2-8f6feafa9594:card_description', 'teaser-card-s024 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '9c0f473de736237731a94613fa4f7bfca906dc2a9eefb49df2e6e8715caa7342|44a38a2a84678de492136fc8fcbacef0b5fa1f2b543ece60210ec503ff341465|44a38a2a84678de492136fc8fcbacef0b5fa1f2b543ece60210ec503ff341465', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Dedicated in AD 32 to the god Bel, the Templo de Bel in Palmyra stood on a tell where human occupation goes back to the third millennium BC, and later became a Christian church."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the temple was dedicated in AD 32 [S2]; it was dedicated to the god Bel [S2]; the Templo de Bel is in Palmyra [S1]; it stood on a tell [S4]; human occupation at the tell goes back to the third millennium BC [S4]; it later became a Christian church [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-041 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Temple of Bel is a temple in Palmyra, Syria [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Bel]; It was consecrated to the god Bel [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Bel]; It was dedicated in AD 32 [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Bel]; It is in Palmyra [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Bel]; It stood on a tell [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Bel]; It stood on a tell with human occupation going back to the third millennium BC [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Bel]; It later became a Christian church [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Bel]"}]'::jsonb),
    ('77127fe3-8116-4567-9b04-aebbe719e5a7'::uuid, 'card_description', 'City walls first built in antiquity, rebuilt by Byzantines, then expanded by Venetians in the 16th century. Parts of both the Byzantine and Venetian walls still stand.', 'Where ancient Cydonia once stood, the Fortifications of Chania ring the city: inner walls first built in antiquity and rebuilt by the Byzantine Empire, outer walls by Venice.', 'teaser-card-s024:77127fe3-8116-4567-9b04-aebbe719e5a7:card_description', 'teaser-card-s024 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', '11172ff711aff433cfdeb95b1bf79435dd7709aa82a3e057d157888b25621c9b|a60f3835bae1748ecfc387b9d7ab4fb9f51faf03484b264dc1fc82c7274a6c28|a60f3835bae1748ecfc387b9d7ab4fb9f51faf03484b264dc1fc82c7274a6c28', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Where ancient Cydonia once stood, the Fortifications of Chania ring the city: inner walls first built in antiquity and rebuilt by the Byzantine Empire, outer walls by Venice."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "ancient Cydonia once stood where Chania is [S5]; the Fortifications of Chania ring the city [S1]; the inner walls were first built in antiquity [S2]; the inner walls were rebuilt by the Byzantine Empire [S2]; the outer walls were built by Venice [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-042 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Fortifications of Chania are defensive walls surrounding the city of Chania (Crete, Greece) [SUPPORTED: https://en.wikipedia.org/wiki/Fortifications_of_Chania]; Ancient Cydonia stood where Chania now is [SUPPORTED: https://en.wikipedia.org/wiki/Fortifications_of_Chania]; The inner walls were first built in antiquity [SUPPORTED: https://en.wikipedia.org/wiki/Fortifications_of_Chania]; The inner walls were rebuilt by the Byzantine Empire [SUPPORTED: https://en.wikipedia.org/wiki/Fortifications_of_Chania]; The outer walls were built by Venice [SUPPORTED: https://en.wikipedia.org/wiki/Fortifications_of_Chania]"}]'::jsonb),
    ('7753067f-ce23-4def-81de-184ce34eefce'::uuid, 'card_description', 'Multi-period site where Bronze Age and early Christian layers stack atop one another. Three distinct occupation epochs were identified, spanning several millennia.', 'North of Leptokarya, Valtos Leptokaryas gave up pits, burial mounds and a woman adorned with earrings of a golden band around a copper spiral and a necklace of gold, bronze and glass.', 'teaser-card-s024:7753067f-ce23-4def-81de-184ce34eefce:card_description', 'teaser-card-s024 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '34002c2574b97386aff4639886eff46a74ca7d0541d753af443a5dd84ff08652|eecbbcbd14eda775278bf1ec5d2bdbd5413f16c718f3d7fe02deaf961b715e33|eecbbcbd14eda775278bf1ec5d2bdbd5413f16c718f3d7fe02deaf961b715e33', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "North of Leptokarya, Valtos Leptokaryas gave up pits, burial mounds and a woman adorned with earrings of a golden band around a copper spiral and a necklace of gold, bronze and glass."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Valtos Leptokaryas lies north of Leptokarya [S2]; the site yielded pits [S4]; the site yielded burial mounds [S4]; it yielded (the remains of) a woman adorned with earrings [S6]; the earrings are of a golden band around a copper spiral [S6]; she wore a necklace with gold, bronze and glass [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-042 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Valtos Leptokaryas is an archaeological site (settlement with cemetery) north of Leptokarya, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Valtos_Leptokaryas]; The site yielded simple pits [SUPPORTED: https://en.wikipedia.org/wiki/Valtos_Leptokaryas]; The site yielded burial mounds [SUPPORTED: https://en.wikipedia.org/wiki/Valtos_Leptokaryas]; A woman''s body was adorned with earrings of a golden band encircling a copper spiral [SUPPORTED: https://en.wikipedia.org/wiki/Valtos_Leptokaryas]; The earrings had a copper spiral core [SUPPORTED: https://en.wikipedia.org/wiki/Valtos_Leptokaryas]; She wore a necklace including gold, bronze and glass [SUPPORTED: https://en.wikipedia.org/wiki/Valtos_Leptokaryas]"}]'::jsonb),
    ('7793574e-f857-4526-bfc4-d9a64281f303'::uuid, 'card_description', 'A stone row stretching across Ringmoor Down, paired with a cairn circle. Dartmoor holds the densest concentration of stone rows in the world.', 'On Ringmoor Down in Devon, the Ringmoor Stone Row and Cairn Circle runs 356 metres, from a standing stone at its northern end to a cairn circle 12.6 metres across.', 'teaser-card-s024:7793574e-f857-4526-bfc4-d9a64281f303:card_description', 'teaser-card-s024 (teaser-card): teaser card, 163 characters, checked PASS, web-verified VERIFIED', '94af0af7999eede0ca03a7f34c72ae5b8b2a9a9b669888bfb534146347a07a56|cdc141680ebb777da991789f31ea34f29144c7bb881533eb69f6949a9bc08930|cdc141680ebb777da991789f31ea34f29144c7bb881533eb69f6949a9bc08930', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On Ringmoor Down in Devon, the Ringmoor Stone Row and Cairn Circle runs 356 metres, from a standing stone at its northern end to a cairn circle 12.6 metres across."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the site is on Ringmoor Down [S1]; it is in Devon [S1]; the stone row runs 356 metres [S4]; a standing stone is at its northern end [S8]; a cairn circle is at the other (southern) end [S6]; the cairn circle is 12.6 metres across [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-042 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Ringmoor Stone Row and Cairn Circle is a prehistoric stone row and cairn circle on Ringmoor Down in Devon [SUPPORTED: https://en.wikipedia.org/wiki/Ringmoor_stone_row_and_cairn_circle]; The site lies on Ringmoor Down in Devon (England) [SUPPORTED: https://en.wikipedia.org/wiki/Ringmoor_stone_row_and_cairn_circle]; The stone row is 356 metres long [SUPPORTED: https://en.wikipedia.org/wiki/Ringmoor_stone_row_and_cairn_circle]; A standing stone terminates the row at the northern end [SUPPORTED: https://en.wikipedia.org/wiki/Ringmoor_stone_row_and_cairn_circle]; The site includes a cairn circle at the other (southern) end of the row [SUPPORTED: https://en.wikipedia.org/wiki/Ringmoor_stone_row_and_cairn_circle]; The cairn circle is 12.6 metres across [SUPPORTED: https://en.wikipedia.org/wiki/Ringmoor_stone_row_and_cairn_circle]"}]'::jsonb),
    ('78c84929-bf4c-4cef-9335-6063ba3337f7'::uuid, 'card_description', 'One of the harder stone circles to spot — sixteen fallen stones considerably overgrown. Located near The Hurlers, a group of three stone circles on Bodmin Moor.', 'On Bodmin Moor, sixteen fallen stones mark the Craddock Moor Stone Circle. John Barnatt has suggested it was placed so the summit of Brown Willy marked the midsummer sunset.', 'teaser-card-s024:78c84929-bf4c-4cef-9335-6063ba3337f7:card_description', 'teaser-card-s024 (teaser-card): teaser card, 173 characters, checked PASS, web-verified VERIFIED', 'c6d09d1bcfa0bbe75e8425c1c107009e9f85e835920ea60963d1913714ba5c4e|45fed1441780a1a5bb804243fdfbc749dfc779cba922bb4a39183a768982756b|45fed1441780a1a5bb804243fdfbc749dfc779cba922bb4a39183a768982756b', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On Bodmin Moor, sixteen fallen stones mark the Craddock Moor Stone Circle. John Barnatt has suggested it was placed so the summit of Brown Willy marked the midsummer sunset."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Craddock Moor Stone Circle is on Bodmin Moor [S1]; it consists of sixteen fallen stones [S3]; John Barnatt has suggested it was placed so the summit of Brown Willy marked the midsummer sunset [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-042 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Craddock Moor Stone Circle is a stone circle on Bodmin Moor [SUPPORTED: https://en.wikipedia.org/wiki/Craddock_Moor_stone_circle]; The circle consists of sixteen fallen stones [SUPPORTED: https://en.wikipedia.org/wiki/Craddock_Moor_stone_circle]; John Barnatt suggested the circle was placed so Brown Willy''s summit marked the midsummer sunset [SUPPORTED: https://en.wikipedia.org/wiki/Craddock_Moor_stone_circle]"}]'::jsonb),
    ('78c9f0a2-2247-4159-87ce-9a0e69e88e28'::uuid, 'card_description', NULL, 'On the narrowest part of a small plateau near Casaglione, the dolmen of Tremeca rests on four rough-hewn granite blocks capped with a slab, its opening turned toward the southeast.', 'teaser-card-s024:78c9f0a2-2247-4159-87ce-9a0e69e88e28:card_description', 'teaser-card-s024 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '5c943c951fe30318a27bfa8952497a7c8af04232f0da29e2c1f50ba694a6c965|d2bbc411035e150adfbefbbea66fd48ea833365291ec48a4145b24a50369e07b|d2bbc411035e150adfbefbbea66fd48ea833365291ec48a4145b24a50369e07b', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On the narrowest part of a small plateau near Casaglione, the dolmen of Tremeca rests on four rough-hewn granite blocks capped with a slab, its opening turned toward the southeast."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the dolmen stands on the narrowest part of a small plateau [S4]; the site is near Casaglione [S2]; Tremeca is a dolmen [S4]; it rests on four rough-hewn granite blocks [S4]; the blocks are capped with a slab [S4]; its opening faces southeast [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-042 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Tremeca is a dolmen near Casaglione (Corsica, France) [SUPPORTED: https://en.wikipedia.org/wiki/Tremeca]; The dolmen stands in the narrowest part of a small plateau [SUPPORTED: https://en.wikipedia.org/wiki/Tremeca]; The dolmen is supported by four rough-hewn blocks [SUPPORTED: https://en.wikipedia.org/wiki/Tremeca]; The blocks are granite [SUPPORTED: https://en.wikipedia.org/wiki/Tremeca]; The blocks are capped with a slab [SUPPORTED: https://en.wikipedia.org/wiki/Tremeca]; The plateau is small [SUPPORTED: https://en.wikipedia.org/wiki/Tremeca]; Its opening faces southeast [SUPPORTED: https://en.wikipedia.org/wiki/Tremeca]"}]'::jsonb),
    ('78dcb136-e26a-4653-b586-6b75dd96ccb4'::uuid, 'card_description', 'The sanctuary might have been dedicated to Apollon since two inscriptions mention him, but another inscription mentions Athena as well.', 'Between Vouni and Soli, by a river delta, the Swedish Cyprus Expedition uncovered the open-air sanctuary of Mersinaki in 1930. Two inscriptions name Apollon, but another names Athena.', 'teaser-card-s024:78dcb136-e26a-4653-b586-6b75dd96ccb4:card_description', 'teaser-card-s024 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'aef87860318d2ac7e75a77a329482b1c1a70b67962d5954eef554902cd01f1d4|78ad87b5b4872e65bae94f4c3535951a9fc8a19fe6ba92acf987d02d45cdaf34|78ad87b5b4872e65bae94f4c3535951a9fc8a19fe6ba92acf987d02d45cdaf34', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Between Vouni and Soli, by a river delta, the Swedish Cyprus Expedition uncovered the open-air sanctuary of Mersinaki in 1930. Two inscriptions name Apollon, but another names Athena."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Mersinaki lies between Vouni and Soli [S1]; the sanctuary is by a river delta [S2]; the Swedish Cyprus Expedition excavated it [S2]; it is an open-air sanctuary [S2]; the excavation was in 1930 [S2]; two inscriptions mention Apollon [S3]; another inscription mentions Athena [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-043 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Mersinaki is an open-air sanctuary [SUPPORTED: https://en.wikipedia.org/wiki/Mersinaki]; Mersinaki is in Cyprus [SUPPORTED: https://en.wikipedia.org/wiki/Mersinaki]; Mersinaki lies between Vouni and Soli [SUPPORTED: https://en.wikipedia.org/wiki/Mersinaki]; The sanctuary lies by a river delta [SUPPORTED: https://en.wikipedia.org/wiki/Mersinaki]; The Swedish Cyprus Expedition uncovered the site [SUPPORTED: https://en.wikipedia.org/wiki/Mersinaki]; The excavation took place in 1930 [SUPPORTED: https://en.wikipedia.org/wiki/Mersinaki]; Two inscriptions name Apollon [SUPPORTED: https://en.wikipedia.org/wiki/Mersinaki]; Another inscription names Athena [SUPPORTED: https://en.wikipedia.org/wiki/Mersinaki]"}]'::jsonb),
    ('7968021c-6036-45f7-96ee-2b8e198a8040'::uuid, 'card_description', 'Perched at the southern tip of a coastal sandy spit, this fort is enclosed by tidal wetlands and dunes. Access on foot is nearly impossible — only a distant bird hide offers a view.', 'Holkham Camp, an Iron Age fort guarded by slope, creek and rampart, is one of two possible sites where Tacitus set the defeat of Iceni rebels by a Roman force in AD 47.', 'teaser-card-s024:7968021c-6036-45f7-96ee-2b8e198a8040:card_description', 'teaser-card-s024 (teaser-card): teaser card, 168 characters, checked PASS, web-verified VERIFIED', '3564573fa61a378acdec05d8c777d6ea0097f722c9157164054e020d4b224968|6ec1d7dbde2d7ae2fd3adccf24b90cde032bec8e28dd5ad7ae95fbaad2526324|6ec1d7dbde2d7ae2fd3adccf24b90cde032bec8e28dd5ad7ae95fbaad2526324', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Holkham Camp, an Iron Age fort guarded by slope, creek and rampart, is one of two possible sites where Tacitus set the defeat of Iceni rebels by a Roman force in AD 47."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Holkham Camp is an Iron Age fort [S1]; it is protected by a slope [S3]; it is protected by a creek [S3]; it has a rampart [S4]; it is one of two possible sites matching Tacitus''s description of the location of the defeat of Iceni rebels [S6]; the rebels were defeated by a Roman force [S6]; the defeat took place in AD 47 [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-043 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Holkham Camp is a fort [SUPPORTED: https://en.wikipedia.org/wiki/Holkham_Camp]; It dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Holkham_Camp]; It is protected by a slope on its western side [SUPPORTED: https://en.wikipedia.org/wiki/Holkham_Camp]; It is protected by a creek on the south-west [SUPPORTED: https://en.wikipedia.org/wiki/Holkham_Camp]; It is protected by a rampart on the east side [SUPPORTED: https://en.wikipedia.org/wiki/Holkham_Camp]; It is one of two possible sites for the location Tacitus describes [SUPPORTED: https://en.wikipedia.org/wiki/Holkham_Camp]; Tacitus describes the defeat of Iceni rebels [SUPPORTED: https://en.wikipedia.org/wiki/Holkham_Camp]; The defeat was by a Roman force [SUPPORTED: https://en.wikipedia.org/wiki/Holkham_Camp]; The defeat took place in AD 47 [SUPPORTED: https://en.wikipedia.org/wiki/Holkham_Camp]"}]'::jsonb),
    ('7aee6833-f789-49f0-8643-afa9830e90ce'::uuid, 'card_description', 'Around 2500 BC, Ganweriwala was one of the Indus Valley''s largest cities — yet it remains unexcavated. Surface finds include unicorn figurines and copper seals from its buried streets.', 'On a dry riverbed in the Cholistan Desert lies Ganweriwal, never properly excavated. From its surface came unicorn figurines, a copper seal and a clay tablet of a deity seated on a throne.', 'teaser-card-s024:7aee6833-f789-49f0-8643-afa9830e90ce:card_description', 'teaser-card-s024 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '6db9030d06f9b8cf471986c08c2700e5a64c7a0de1c2aa08fffa8ee3fcdbb99b|78087d5bb0ef6be54774b1b870f943a4ea5fc9b1610659868c29ed11f9cc4746|78087d5bb0ef6be54774b1b870f943a4ea5fc9b1610659868c29ed11f9cc4746', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On a dry riverbed in the Cholistan Desert lies Ganweriwal, never properly excavated. From its surface came unicorn figurines, a copper seal and a clay tablet of a deity seated on a throne."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Ganweriwal lies on a dry riverbed [S4]; it is in the Cholistan Desert [S1, S4]; it has never been properly excavated [S2]; unicorn figurines came from its surface finds [S3]; a copper seal came from its surface finds [S3]; a clay tablet came from its surface finds [S3]; the clay tablet shows a deity seated on a throne [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-043 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Ganweriwal is an archaeological site (an Indus Valley city) [SUPPORTED: https://en.wikipedia.org/wiki/Ganweriwal]; It lies in the Cholistan Desert [SUPPORTED: https://en.wikipedia.org/wiki/Ganweriwal]; It lies on a dry riverbed [SUPPORTED: https://en.wikipedia.org/wiki/Ganweriwal]; It has never been properly excavated [SUPPORTED: https://en.wikipedia.org/wiki/Ganweriwal]; Unicorn figurines came from surface collection [SUPPORTED: https://en.wikipedia.org/wiki/Ganweriwal]; A copper seal came from surface collection [SUPPORTED: https://en.wikipedia.org/wiki/Ganweriwal]; A clay tablet came from surface collection [SUPPORTED: https://en.wikipedia.org/wiki/Ganweriwal]; The clay tablet shows a deity [SUPPORTED: https://en.wikipedia.org/wiki/Ganweriwal]; The deity is seated on a throne [SUPPORTED: https://en.wikipedia.org/wiki/Ganweriwal]"}]'::jsonb),
    ('7bdca82b-3519-44ef-9229-ee59f43c179c'::uuid, 'card_description', 'Inhabited since 2200 BC with over 80 ruins and Inca terraces on its rocky slopes. Inca mythology holds this island as the birthplace of the sun itself.', 'On Isla del Sol in Lake Titicaca, where the Incas believed the sun god was born, people have lived since at least 2200 BC, among ruins like the labyrinth-like building Chinkana.', 'teaser-card-s024:7bdca82b-3519-44ef-9229-ee59f43c179c:card_description', 'teaser-card-s024 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '050ca9fee5b2e82c7fddf1b7df4cc007d763cb983101c9800f5b6961dbacf6c6|3e77adc1a4bf052d13b07f3fb2858e27a6d01e6ebeb3bf81b79688df3b9dab6e|3e77adc1a4bf052d13b07f3fb2858e27a6d01e6ebeb3bf81b79688df3b9dab6e', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On Isla del Sol in Lake Titicaca, where the Incas believed the sun god was born, people have lived since at least 2200 BC, among ruins like the labyrinth-like building Chinkana."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Isla del Sol is in Lake Titicaca [S1]; the Incas believed the sun god was born there [S4]; people have lived there since at least 2200 BC [S6]; among its ruins is Chinkana [S3]; Chinkana is a labyrinth-like building [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-043 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Isla del Sol is an island in Lake Titicaca with ruins [SUPPORTED: https://en.wikipedia.org/wiki/Isla_del_Sol]; The Incas believed the sun god was born there [SUPPORTED: https://en.wikipedia.org/wiki/Isla_del_Sol]; People have lived on the island since at least 2200 BC [SUPPORTED: https://en.wikipedia.org/wiki/Isla_del_Sol]; There are ruins on the island [SUPPORTED: https://en.wikipedia.org/wiki/Isla_del_Sol]; Chinkana is a ruin on the island [SUPPORTED: https://en.wikipedia.org/wiki/Isla_del_Sol]; Chinkana is a labyrinth-like building [SUPPORTED: https://en.wikipedia.org/wiki/Isla_del_Sol]"}]'::jsonb),
    ('7c97de3a-0401-4cd9-892a-79450990b3ce'::uuid, 'card_description', 'In the Roman era, a temple dedicated to Jupiter was erected nearby along with a mansio serving travellers along the pass, and it is thought that Carthaginian general Hannibal used this route.', 'At the summit of the Little St Bernard Pass, the road cuts through a stone circle 72 m across, where a standing stone once stood. Hannibal is thought to have used this route.', 'teaser-card-s024:7c97de3a-0401-4cd9-892a-79450990b3ce:card_description', 'teaser-card-s024 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', '02f7ef2c4880fc82a74f8c4a5eac46d96619fab79c3a7f1b5436b35f8afcb155|f62b35ab421b1208c325c0b6a3b5bd33d274c70d58bcebccf315d63aedef7c74|f62b35ab421b1208c325c0b6a3b5bd33d274c70d58bcebccf315d63aedef7c74', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "At the summit of the Little St Bernard Pass, the road cuts through a stone circle 72 m across, where a standing stone once stood. Hannibal is thought to have used this route."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "at the summit of the Little St Bernard Pass the road cuts through a stone circle [S4]; the stone circle is 72 m across [S4]; a standing stone once stood there (in the middle) [S5]; Hannibal is thought to have used this route [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-043 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Little St Bernard Pass is an Alpine mountain pass on the France-Italy border (summit with an ancient stone circle) [SUPPORTED: https://en.wikipedia.org/wiki/Little_St_Bernard_Pass]; At the summit the road cuts through a stone circle 72 m across [SUPPORTED: https://en.wikipedia.org/wiki/Little_St_Bernard_Pass]; A standing stone once stood in it [SUPPORTED: https://en.wikipedia.org/wiki/Little_St_Bernard_Pass]; Hannibal is thought to have used this route [SUPPORTED: https://en.wikipedia.org/wiki/Little_St_Bernard_Pass]"}]'::jsonb),
    ('7d8df981-b89f-4d88-809d-205d2d11c160'::uuid, 'card_description', 'The Taghlar cave is an archaeological site that was inhabited by prehistoric humans of the Mousterian culture during the Paleolithic.', 'On the banks of the Guruchay River, Taghlar Cave was home to Mousterian people 64-24 thousand years ago. Digging yielded more than 7,000 stone tools and remains of horse, deer and bull.', 'teaser-card-s024:7d8df981-b89f-4d88-809d-205d2d11c160:card_description', 'teaser-card-s024 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', 'e9af1091c4908aedc48f484b446f8832847aa6e3c6c280043194f9fe67bce44f|b2a357c28343359cbaf7b52d1b53bb269607211f9b7c4aad1d5cadd3d1b6fcf2|b2a357c28343359cbaf7b52d1b53bb269607211f9b7c4aad1d5cadd3d1b6fcf2', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On the banks of the Guruchay River, Taghlar Cave was home to Mousterian people 64-24 thousand years ago. Digging yielded more than 7,000 stone tools and remains of horse, deer and bull."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Taghlar Cave is on the banks of the Guruchay River [S2]; it was inhabited by people of the Mousterian culture [S1]; people lived there 64-24 thousand years ago [S3]; excavation yielded more than 7,000 stone tools [S5]; remains of horse were found [S7]; remains of deer were found [S7]; remains of bull were found [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-044 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Taghlar Cave is an archaeological cave site (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Taghlar_Cave]; Taghlar Cave lies on the banks of 