    ('7e88e3ce-568c-4cea-aa71-79713b290df1'::uuid, 'card_description', 'Saka kurgans from the 5th-3rd century BC that contained golden jewelry and horses buried beside their owners. Permafrost preserved organic materials in extraordinary detail.', NULL, 'teaser-card-s024:7e88e3ce-568c-4cea-aa71-79713b290df1:card_description', 'teaser-card-s024 (card-clear-unproven-after-verify): card cleared (unproven-after-verify)', '||d4cc57e388ea1c10ec59367ef8dda731aa6d1cd72cc8322f0d515f576a1bafc8', '[{"source": "lane WB run wb-ws-2026-09-27-05: unproven-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The web check could not prove: Berel kurgan is an archaeological site of kurgans in eastern Kazakhstan (central claim); The web check could not prove: Berel Kurgan is an archaeological site of Early Saka kurgans in eastern Kazakhstan; The web check could not prove: The site is in Kazakhstan"}]'::jsonb),
    ('7ec11470-fc03-404c-a2bc-db2f6507bb4a'::uuid, 'card_description', 'Founded by Greek colonists from Corinth in the 7th century BC and later known as Dyrrachium. It served as the starting point of the Via Egnatia to Byzantium.', 'Durrës, founded as Epidamnos around the 7th century BC by Greek colonists from Corinth and Corcyra, is also known as Dyrrachium. The Via Egnatia started here and led east to Constantinople.', 'teaser-card-s024:7ec11470-fc03-404c-a2bc-db2f6507bb4a:card_description', 'teaser-card-s024 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'd81153af8f6419ff5f04dde27cc799e57475d6f06f353818d9370deb9cff3cec|427cab80f554831315d1963afcff9ae90adb61964bf9e57bd50a716fb2294adc|427cab80f554831315d1963afcff9ae90adb61964bf9e57bd50a716fb2294adc', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Durrës, founded as Epidamnos around the 7th century BC by Greek colonists from Corinth and Corcyra, is also known as Dyrrachium. The Via Egnatia started here and led east to Constantinople."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Durres was founded as Epidamnos [S1]; it was founded around the 7th century BC [S1]; the founders were Greek colonists from Corinth and Corcyra [S1]; it is also known as Dyrrachium [S2]; the Via Egnatia started in the city [S3]; the Via Egnatia led east to Constantinople [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify2-003 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Durrës is a city (settlement) in Albania [SUPPORTED: https://en.wikipedia.org/wiki/Durr%C3%ABs]; It was founded as Epidamnos [SUPPORTED: https://en.wi