    ('96cc1d5e-207e-4b43-b14e-a0854e10e7c2'::uuid, 'card_description', 'Elliptical Shropshire hillfort with up to four concentric ditches and two well-preserved entrances ringing the summit of Sunnyhill. The neat oval shape earns it a reputation as a spectacular example.', 'Storms in the 1970s and 1980s led to the removal of woodland from the crown of Sunnyhill, where the Iron Age hill fort Bury Ditches keeps a neat oval and two well preserved entrance ways.', 'teaser-card-s024:96cc1d5e-207e-4b43-b14e-a0854e10e7c2:card_description', 'teaser-card-s024 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '3fd68d8cd9a84683ce8066d25259bf65467040ac079d62ddf1dbcb29deef9337|69f2499b6bcc6bf452c83e15a79c9b64655d48f741e9f58b2139611aad26a503|69f2499b6bcc6bf452c83e15a79c9b64655d48f741e9f58b2139611aad26a503', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Storms in the 1970s and 1980s led to the removal of woodland from the crown of Sunnyhill, where the Iron Age hill fort Bury Ditches keeps a neat oval and two well preserved entrance ways."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "storms in the 1970s and 1980s led to removal of woodland [S2]; the woodland was on the crown of the hill, Sunnyhill [S2, S3]; Bury Ditches is an Iron Age hill fort [S1]; it keeps a neat oval shape [S3]; it has two well preserved entrance ways [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify2-005 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Bury Ditches is an Iron Age hill fort in the Shropshire Hills, England [SUPPORTED: https://en.wikipedia.org/wiki/Bury_Ditches]; Storms in the 1970s and 1980s led to the removal of woodland from the site on the crown of the hill [SUPPORTED: https://en.wikipedia.org/wiki/Bury_Ditches]; The hill is called Sunnyhill [SUPPORTED: https://en.wikipedia.org/wiki/Bury_Ditches]; The fort forms a neat oval shape [SUPPORTED: https://en.wikipedia.org/wiki/Bury_Ditches]; The fort has two well preserved entrance ways [SUPPORTED: https://en.wikipedia.org/wiki/Bury_Ditches]"}]'::jsonb),
    ('991bd627-65d9-40d3-a97d-dfa879756da0'::uuid, 'card_description', NULL, 'Sybaris, founded around 720 BC by Achaean and Troezenian settlers, ruled over 4 tribes and 25 cities. Its ruins became forgotten, buried by sediment from the Crati river.', 'teaser-card-s024:991bd627-65d9-40d3-a97d-dfa879756da0:card_description', 'teaser-card-s024 (teaser-card): teaser card, 170 characters, checked PASS, web-verified VERIFIED', '4b53d84ebec262221c15fd078d8e5e5c0149f8cc87e509f3c4cb0e21961439fc|4e75861e16a33f5874cd50cfee6d586a167ce8e8fe43fa0825c70fdc7a0b9a4b|4e75861e16a33f5874cd50cfee6d586a167ce8e8fe43fa0825c70fdc7a0b9a4b', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Sybaris, founded around 720 BC by Achaean and Troezenian settlers, ruled over 4 tribes and 25 cities. Its ruins became forgotten, buried by sediment from the Crati river."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Sybaris was founded around 720 BC [S2]; founded by Achaean and Troezenian settlers [S2]; it ruled over 4 tribes and 25 cities [S8]; its ruins became forgotten [S3]; the ruins were buried by sediment from the Crati river [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify2-005 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Sybaris was an ancient Greek city (archaeological site) in Calabria, Italy [SUPPORTED: https://en.wikipedia.org/wiki/Sybaris]; Sybaris was founded around 720 BC [SUPPORTED: https://en.wikipedia.org/wiki/Sybaris]; Founded by Achaean settlers [SUPPORTED: https://en.wikipedia.org/wiki/Sybaris]; Founded by Troezenian settlers as well [SUPPORTED: https://en.wikipedia.org/wiki/Sybaris]; Sybaris ruled over 4 tribes [SUPPORTED: https://en.wikipedia.org/wiki/Sybaris]; Sybaris ruled over 25 cities [SUPPORTED: https://en.wikipedia.org/wiki/Sybaris]; The ruins became forgotten [SUPPORTED: https://en.wikipedia.org/wiki/Sybaris]; The ruins were buried by sediment from the Crati river [SUPPORTED: https://en.wikipedia.org/wiki/Sybaris]"}]'::jsonb),
    ('9a941093-043f-4287-b188-aebddd81df62'::uuid, 'card_description', 'A pair of Neolithic barrows of the Cotswold-Severn type, one of which was completely excavated. The excavation revealed the full construction sequence of a 5,000-year-old burial mound.', 'At the Hazleton Long Barrows, two Neolithic chambered tombs of approximately 3700-3600 BCE in Gloucestershire, excavation revealed one of the earliest-known family trees from DNA analysis.', 'teaser-card-s024:9a941093-043f-4287-b188-aebddd81df62:card_description', 'teaser-card-s024 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'ec4941f348405872a2dfa18f77f1f63897b68b78d74cc749311ae5c998c7b9d4|de6bdd0002c541ee4fd242d8e48aed2038cfbb84d5f7de5629343d0999da72ad|de6bdd0002c541ee4fd242d8e48aed2038cfbb84d5f7de5629343d0999da72ad', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "At the Hazleton Long Barrows, two Neolithic chambered tombs of approximately 3700-3600 BCE in Gloucestershire, excavation revealed one of the earliest-known family trees from DNA analysis."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Hazleton Long Barrows are two Neolithic chambered tombs [S1]; they date to approximately 3700-3600 BCE [S2]; they are in Gloucestershire [S1]; excavation revealed one of the earliest-known family trees from DNA analysis [S3, S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-054 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Hazleton Long Barrows are Neolithic chambered tombs located in Gloucestershire, England [SUPPORTED: https://en.wikipedia.org/wiki/Hazleton_long_barrows]; There are two tombs [SUPPORTED: https://en.wikipedia.org/wiki/Hazleton_long_barrows]; The tombs date to approximately 3700-3600 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Hazleton_long_barrows]; Excavation revealed one of the earliest-known family trees from DNA analysis [SUPPORTED: https://en.wikipedia.org/wiki/Hazleton_long_barrows]"}]'::jsonb),
    ('9b14cbe4-f49c-4abf-8f51-c3bc75f54b00'::uuid, 'card_description', 'Maya site 350 BC-250 AD in the Peten Basin. Teotihuacano imagery on La Sufricaya stelae and murals suggests foreign or non-Maya occupation, a rare contact between distant Mesoamerican cultures.', 'In the Petén Basin, the Maya site of La Sufricaya lies approximately 1.2 km west of Holmul, and how the two sites related in the Classic period is still being investigated.', 'teaser-card-s024:9b14cbe4-f49c-4abf-8f51-c3bc75f54b00:card_description', 'teaser-card-s024 (teaser-card): teaser card, 172 characters, checked PASS, web-verified VERIFIED', 'e83344a97a5f7ed45511126cb7875c95e6aa0eac16d87ba4f6e10fa686cb7c2b|6017cb9006ae818b172bd69e13f53efb9a8e0e9905197e7d4c4fb7362c4ceb9a|6017cb9006ae818b172bd69e13f53efb9a8e0e9905197e7d4c4fb7362c4ceb9a', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In the Petén Basin, the Maya site of La Sufricaya lies approximately 1.2 km west of Holmul, and how the two sites related in the Classic period is still being investigated."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "La Sufricaya is in the Petén Basin [S1]; it is a Maya site [S1]; it lies approximately 1.2 km west of Holmul [S2]; the relationship between the two sites in the Classic period is still being investigated (an open question) [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-054 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "La Sufricaya is a Maya archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/La_Sufricaya]; It is located in the Petén Basin [SUPPORTED: https://en.wikipedia.org/wiki/La_Sufricaya]; It lies approximately 1.2 km west of Holmul [SUPPORTED: https://en.wikipedia.org/wiki/La_Sufricaya]; How the two sites related in the Classic period is still being investigated [SUPPORTED: https://en.wikipedia.org/wiki/La_Sufricaya]; The relationship concerns the Classic period [SUPPORTED: https://en.wikipedia.org/wiki/La_Sufricaya]"}]'::jsonb),
    ('9b42d08a-5048-42bb-8527-8e26a4f6bbe2'::uuid, 'card_description', 'Late La Tène Scordisci site beside the Danube, southeast of Vukovar, with a settlement and necropolis. Rescue excavations in the 1970s–80s traced the tribe''s deep reach into eastern Slavonia.', 'At Sotin lies a settlement of the Pannonian Kornakata tribe, and the archaeological finds speak of life here from the Copper Age to the Younger Iron Age and the Celtic Skordisks.', 'teaser-card-s024:9b42d08a-5048-42bb-8527-8e26a4f6bbe2:card_description', 'teaser-card-s024 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '229907c09e87cfff3bc6c02cc1a2ed6260fd24d0e3b33b68018247fbc96456a8|2b0c99c5d8d5fb17f3b9f48f4ee4fcf0220dc34494e93e186f707d122d011e14|2b0c99c5d8d5fb17f3b9f48f4ee4fcf0220dc34494e93e186f707d122d011e14', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "At Sotin lies a settlement of the Pannonian Kornakata tribe, and the archaeological finds speak of life here from the Copper Age to the Younger Iron Age and the Celtic Skordisks."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "at Sotin there is a settlement of the Pannonian Kornakata tribe [S1]; archaeological finds speak of life in the Sotin area from the Copper Age to the Younger Iron Age [S2]; the finds also speak of the Celtic Skordisks [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-054 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Sotin has an archaeological site with a settlement [SUPPORTED: https://en.wikipedia.org/wiki/Sotin]; The settlement is of the Pannonian Kornakata tribe [SUPPORTED: https://en.wikipedia.org/wiki/Sotin]; Finds show life from the Copper Age [SUPPORTED: https://en.wikipedia.org/wiki/Sotin]; Finds show life to the Younger Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Sotin]; Finds show life of the Celtic Skordisks [SUPPORTED: https://en.wikipedia.org/wiki/Sotin]"}]'::jsonb),
    ('9b4f553e-24bf-4860-9790-4f8184426360'::uuid, 'card_description', 'A 2nd-century Roman triumphal arch, 5.6 metres wide and 11.2 metres tall, at the southern end of the city''s cardo. Both facades were decorated identically.', 'Once brightly coloured, the Porte Noire in Besançon was blackened by centuries of fire: a limestone Roman triumphal arch 11.2 metres high, dated to the reign of Marcus Aurelius.', 'teaser-card-s024:9b4f553e-24bf-4860-9790-4f8184426360:card_description', 'teaser-card-s024 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '4de4618a418220992b68c2bd1837b1aa1b841aeb531b6d3615d17674840b65fe|f75b60b2cb4a8c214aa642d5958d77218852be083cb025fae0d3af90c094812c|f75b60b2cb4a8c214aa642d5958d77218852be083cb025fae0d3af90c094812c', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Once brightly coloured, the Porte Noire in Besançon was blackened by centuries of fire: a limestone Roman triumphal arch 11.2 metres high, dated to the reign of Marcus Aurelius."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Porte Noire was originally brightly coloured [S6]; it is in Besançon [S1]; it was blackened by centuries of fire [S6]; it is made of limestone [S2]; it is a Roman triumphal arch [S1]; it is 11.2 metres high [S3]; it is dated to the reign of Marcus Aurelius [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-054 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Porte Noire is a Roman triumphal arch [SUPPORTED: https://en.wikipedia.org/wiki/Porte_Noire]; It is in Besançon [SUPPORTED: https://en.wikipedia.org/wiki/Porte_Noire]; The arch is made of limestone [SUPPORTED: https://en.wikipedia.org/wiki/Porte_Noire]; It is 11.2 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Porte_Noire]; It is dated to the reign of Marcus Aurelius [SUPPORTED: https://en.wikipedia.org/wiki/Porte_Noire]; It was once brightly coloured [SUPPORTED: https://en.wikipedia.org/wiki/Porte_Noire]; It was blackened by centuries of fire [SUPPORTED: https://en.wikipedia.org/wiki/Porte_Noire]"}]'::jsonb),
    ('9ba7c034-6aec-492e-b66e-4541ce3c987c'::uuid, 'card_description', 'Home of the ancient Olympic Games for over 1,000 years, from the 8th century BC to the 4th century AD. Over 760 buildings once filled this sanctuary to Zeus.', 'In the valley of the Alfeiós River lies Olympia, where tradition dates the first games to 776 BC. Pausanias told of over 70 temples; its finds include the Hermes of Praxiteles.', 'teaser-card-s024:9ba7c034-6aec-492e-b66e-4541ce3c987c:card_description', 'teaser-card-s024 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '8f49bf7b678714a9fcb6ce2a3eedca2c4aebc12a06dafd70aeee2e44e85c2af3|f93cdfa93ad201d0d2c81d5f226195ee08351aa91f92a0467047cb004eb29c73|f93cdfa93ad201d0d2c81d5f226195ee08351aa91f92a0467047cb004eb29c73', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In the valley of the Alfeiós River lies Olympia, where tradition dates the first games to 776 BC. Pausanias told of over 70 temples; its finds include the Hermes of Praxiteles."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Olympia lies in the valley of the Alfeios River [S1]; tradition dates the first games at Olympia to 776 BC [S3]; Pausanias reported over 70 temples [S2]; the finds from Olympia include the Hermes of Praxiteles [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-054 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Olympia is an ancient sanctuary/archaeological site in Greece in the valley of the Alfeiós River [SUPPORTED: https://en.wikipedia.org/wiki/Olympia,_Greece]; Tradition dates the first games to 776 BC [SUPPORTED: https://en.wikipedia.org/wiki/Olympia,_Greece]; Pausanias told of over 70 temples [SUPPORTED: https://en.wikipedia.org/wiki/Olympia,_Greece]; Its finds include the Hermes of Praxiteles [SUPPORTED: https://en.wikipedia.org/wiki/Hermes_and_the_Infant_Dionysus]"}]'::jsonb),
    ('9bae60a8-363b-4c0a-a470-87836fcc9158'::uuid, 'card_description', 'A Mesolithic coastal settlement from around 8800 BC, the oldest known in the Aegean islands. Stone tools, tombs, and structures show permanent habitation millennia before farming arrived.', 'On Kythnos lies Maroulas, the only open area Mesolithic settlement whose architecture survives: round buildings 3 to 4 m across, tombs and quartz tools, from 8800 to 8600 BC.', 'teaser-card-s024:9bae60a8-363b-4c0a-a470-87836fcc9158:card_description', 'teaser-card-s024 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', '0deeaf71cced1abf0d098035d1212b9615f6fb0b5cadab21bf7b092fd65ce43f|61268bfab3e1ec3ba3c209aab0a5542d18fa93f5676dd58e6fe870f818408ef3|61268bfab3e1ec3ba3c209aab0a5542d18fa93f5676dd58e6fe870f818408ef3', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On Kythnos lies Maroulas, the only open area Mesolithic settlement whose architecture survives: round buildings 3 to 4 m across, tombs and quartz tools, from 8800 to 8600 BC."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Maroulas is on Kythnos [S1]; Maroulas is a Mesolithic settlement [S2]; it is the only open area Mesolithic settlement whose architecture has been preserved [S4]; its buildings were round [S5]; the buildings were 3 to 4 m in diameter [S5]; tombs have been found there [S3]; quartz tools have been found there [S3, S7]; the settlement dates from 8800 to 8600 BC [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-055 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Maroulas is a Mesolithic settlement [SUPPORTED: https://en.wikipedia.org/wiki/Maroulas,_Kythnos]; It lies on Kythnos, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Maroulas,_Kythnos]; It is the only open area Mesolithic settlement whose architecture survives [SUPPORTED: https://en.wikipedia.org/wiki/Maroulas,_Kythnos]; Its buildings were round [SUPPORTED: https://en.wikipedia.org/wiki/Maroulas,_Kythnos]; The round buildings were 3 to 4 m across [SUPPORTED: https://en.wikipedia.org/wiki/Maroulas,_Kythnos]; Tombs were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Maroulas,_Kythnos]; Quartz tools were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Maroulas,_Kythnos]; The settlement dates from 8800 to 8600 BC [SUPPORTED: https://en.wikipedia.org/wiki/Maroulas,_Kythnos]"}]'::jsonb),
    ('9c3e1746-6da1-412c-aeb3-eb61cb3cafbb'::uuid, 'card_description', 'A 1st or 2nd century-related settlement with an area of circa 30 ha and a cemetery are near Qalagah.', 'Near Qalagah lie a cemetery and a settlement of circa 30 ha tied to the 1st or 2nd century. Near the village in 1899, a silver plate turned up: a mounted Nereid among tritons and cupids.', 'teaser-card-s024:9c3e1746-6da1-412c-aeb3-eb61cb3cafbb:card_description', 'teaser-card-s024 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '45032c5cbf13ae9be54622815f91201da263e0acbbc96397e48bb91a567567fb|9e6f903d357f9ff576c6bc51d841ebbcc20baf810a1404d786268fff883468ac|9e6f903d357f9ff576c6bc51d841ebbcc20baf810a1404d786268fff883468ac', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Near Qalagah lie a cemetery and a settlement of circa 30 ha tied to the 1st or 2nd century. Near the village in 1899, a silver plate turned up: a mounted Nereid among tritons and cupids."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "a cemetery lies near Qalagah [S1]; a settlement lies near Qalagah [S1]; the settlement covers circa 30 ha [S1]; the settlement is related to the 1st or 2nd century [S1]; a silver plate was found near the village in 1899 [S2]; the plate shows a mounted Nereid [S3]; the Nereid is among tritons and cupids [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-055 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "A settlement lies near Qalagah (a village in Azerbaijan) [SUPPORTED: https://en.wikipedia.org/wiki/Qalagah]; A cemetery lies near Qalagah [SUPPORTED: https://en.wikipedia.org/wiki/Qalagah]; The settlement covers circa 30 ha [SUPPORTED: https://en.wikipedia.org/wiki/Qalagah]; The settlement is tied to the 1st or 2nd century [SUPPORTED: https://en.wikipedia.org/wiki/Qalagah]; A silver plate was found near the village in 1899 [SUPPORTED: https://en.wikipedia.org/wiki/Qalagah]; The plate shows a mounted Nereid [SUPPORTED: https://en.wikipedia.org/wiki/Qalagah]; The Nereid is among tritons and cupids [SUPPORTED: https://en.wikipedia.org/wiki/Qalagah]"}]'::jsonb),
    ('9c64a3f6-8874-4441-b6c8-52428a1d45e5'::uuid, 'card_description', 'Occupied 12,000-7,000 years ago by Hoabinhian hunter-gatherers at 650 m elevation in Mae Hong Son Province. Excavated in the 1960s by Chester Gorman; the Salween River flows less than 50 km away.', 'On a hillside 650 m up, above a small stream, Spirit Cave sheltered Hoabinhian hunter-gatherers in four brief periods between 12,000 to 7,000 uncalibrated radiocarbon years ago.', 'teaser-card-s024:9c64a3f6-8874-4441-b6c8-52428a1d45e5:card_description', 'teaser-card-s024 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '1b83f6fe8a9c6cb2bd8ba83c8d8492efbc28fbcb3c54f57cb24a6f76845bd476|ffd236673a067acc5ee6aa032c7a2db25e35a54d63dea4d03dcdfb05ac1b76d5|ffd236673a067acc5ee6aa032c7a2db25e35a54d63dea4d03dcdfb05ac1b76d5', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On a hillside 650 m up, above a small stream, Spirit Cave sheltered Hoabinhian hunter-gatherers in four brief periods between 12,000 to 7,000 uncalibrated radiocarbon years ago."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Spirit Cave is on a hillside [S4]; it lies at an elevation of 650 m [S4]; it overlooks a small stream [S4]; it was occupied by Hoabinhian hunter-gatherers [S2, S6]; it was occupied in four brief periods [S2]; the occupation fell between 12,000 and 7,000 uncalibrated radiocarbon years ago [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-055 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Spirit Cave is a cave archaeological site in Thailand [SUPPORTED: https://en.wikipedia.org/wiki/Spirit_Cave_(Thailand)]; It lies on a hillside [SUPPORTED: https://en.wikipedia.org/wiki/Spirit_Cave_(Thailand)]; It lies 650 m up [SUPPORTED: https://en.wikipedia.org/wiki/Spirit_Cave_(Thailand)]; It lies above a small stream [SUPPORTED: https://en.wikipedia.org/wiki/Spirit_Cave_(Thailand)]; It was occupied in four brief periods [SUPPORTED: https://en.wikipedia.org/wiki/Spirit_Cave_(Thailand)]; The periods fall between 12,000 and 7,000 uncalibrated radiocarbon years ago [SUPPORTED: https://en.wikipedia.org/wiki/Spirit_Cave_(Thailand)]; The occupants were Hoabinhian [SUPPORTED: https://en.wikipedia.org/wiki/Spirit_Cave_(Thailand)]; The occupants were hunter-gatherers [SUPPORTED: https://en.wikipedia.org/wiki/Spirit_Cave_(Thailand)]"}]'::jsonb),
    ('9c776b7e-cc75-46e4-a169-2aa16b47ae86'::uuid, 'card_description', 'A Roman agricultural estate occupied from the 1st to 4th century AD. A monastery was later built directly on the villa''s foundations.', 'In the southern Alentejo lie the Roman Ruins of São Cucufate, the remains of a Roman-era farm in Vila de Frades. Jorge Alarcão and R. Etienne began the first excavations in 1979.', 'teaser-card-s024:9c776b7e-cc75-46e4-a169-2aa16b47ae86:card_description', 'teaser-card-s024 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '8647c400c37743866ec5b4b2830b3e997c42fd3af7a9e604e857ed6b96f092a2|ecb5c307be25539dbd2fcc59ea6111511ae89a2e4150b073bdddf6a6e519d839|ecb5c307be25539dbd2fcc59ea6111511ae89a2e4150b073bdddf6a6e519d839', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In the southern Alentejo lie the Roman Ruins of São Cucufate, the remains of a Roman-era farm in Vila de Frades. Jorge Alarcão and R. Etienne began the first excavations in 1979."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the ruins lie in the southern Alentejo [S1]; they are the remains of a Roman-era farm [S1]; they are in Vila de Frades [S1]; Jorge Alarcao and R. Etienne began the first excavations [S2]; the first excavations began in 1979 [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-055 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The site is the remains of a Roman-era farm [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_S%C3%A3o_Cucufate]; It lies in the southern Alentejo [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_S%C3%A3o_Cucufate]; It lies in Vila de Frades [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_S%C3%A3o_Cucufate]; Jorge Alarcão and R. Etienne led the first excavations [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_S%C3%A3o_Cucufate]; The first excavations began in 1979 [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_S%C3%A3o_Cucufate]"}]'::jsonb),
    ('9cd5b89c-3734-4dc0-9181-a23eaaffac23'::uuid, 'card_description', 'The site is a collection of 34 structures, with the tallest temple being about 25 meters in height, situated around a central acropolis.', 'High above where the Macal River meets the Mopan, Cahal Pech gathers 34 Maya structures around a central acropolis, abandoned in the 9th century CE for unknown reasons.', 'teaser-card-s024:9cd5b89c-3734-4dc0-9181-a23eaaffac23:card_description', 'teaser-card-s024 (teaser-card): teaser card, 168 characters, checked PASS, web-verified VERIFIED', '423b010f7f308c066c9f7ed8c2c5d524c81dcf2688657b2af7d042e6276fd1d2|78923fda2b26a8ec3f744e63978bd2289ef9a11e9c971441c2d0a1db815fc504|78923fda2b26a8ec3f744e63978bd2289ef9a11e9c971441c2d0a1db815fc504', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "High above where the Macal River meets the Mopan, Cahal Pech gathers 34 Maya structures around a central acropolis, abandoned in the 9th century CE for unknown reasons."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Cahal Pech sits high above the confluence of the Macal and Mopan rivers [S2]; it has 34 structures [S3]; it is a Maya site [S1]; the structures are arranged around a central acropolis [S3]; it was abandoned in the 9th century CE [S4]; the reasons for its abandonment are unknown [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-055 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Cahal Pech is a Maya site in Belize [SUPPORTED: https://en.wikipedia.org/wiki/Cahal_Pech]; It sits high above the Macal River [SUPPORTED: https://en.wikipedia.org/wiki/Cahal_Pech]; It overlooks where the Macal River meets the Mopan River [SUPPORTED: https://en.wikipedia.org/wiki/Cahal_Pech]; It has 34 structures [SUPPORTED: https://en.wikipedia.org/wiki/Cahal_Pech]; The structures are arranged around a central acropolis [SUPPORTED: https://en.wikipedia.org/wiki/Cahal_Pech]; It was abandoned in the 9th century CE [SUPPORTED: https://en.wikipedia.org/wiki/Cahal_Pech]; The reasons for abandonment are unknown [SUPPORTED: https://en.wikipedia.org/wiki/Cahal_Pech]"}]'::jsonb),
    ('9e2b99df-4b4c-41cb-80d3-879a5812e7ed'::uuid, 'card_description', 'The basilica''s large size is due to the additions and modifications made by the various Roman and Byzantine leaders in the 4th and 5th century.', NULL, 'teaser-card-s024:9e2b99df-4b4c-41cb-80d3-879a5812e7ed:card_description', 'teaser-card-s024 (card-clear-failed-after-verify-rewrite): card cleared (failed-after-verify-rewrite)', '||4d5703cca4fa1c5f90062f65aa69806b017f562222d7a79d72bec54506c123e8', '[{"source": "lane WB run wb-ws-2026-09-27-05: failed-after-verify-rewrite", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The web check contradicts: Crispina''s martyrdom took place in 305 CE (https://en.wikipedia.org/wiki/Crispina_of_Numidia: \"Crispina (died 5 December, 304)\"); No sentence of the description supports the claim: the mosaic floors and the piscina are in the open-air atrium; The card''s list ''Mosaic floors, a massive piscina carved into the wall and a four-lobed fountain in an open-air atrium'' places all three in the atrium, but S5 puts the mosaic floors at the entrance pathway into the forecourt and S6 puts the piscina in the wall leading to the atrium; only the fountain is said to be in the atrium (S7). Rewrite so that only the fountain is placed in the atrium."}]'::jsonb),
    ('9f795d88-5e93-4fdb-9bde-0708ddb21b6d'::uuid, 'card_description', 'A Roman buttress dam over 600 meters long but less than 5 meters high. It served double duty: irrigating farmland and supplying water to the nearby town.', 'On the River Amarguillo lie the ruins of the Consuegra Dam, a Roman buttress dam of the 3rd or 4th century AD: less than 5 metres high, yet remarkably long, over 600 metres.', 'teaser-card-s024:9f795d88-5e93-4fdb-9bde-0708ddb21b6d:card_description', 'teaser-card-s024 (teaser-card): teaser card, 173 characters, checked PASS, web-verified VERIFIED', '64f3e93f8be18f52696dc964a2e2e4b8637645d11ba0ed4d3967513c7659c346|216c3bd7799efac800d6b38bdeb651be2a65fbd5868f0630b1e35d025c485c8c|216c3bd7799efac800d6b38bdeb651be2a65fbd5868f0630b1e35d025c485c8c', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On the River Amarguillo lie the ruins of the Consuegra Dam, a Roman buttress dam of the 3rd or 4th century AD: less than 5 metres high, yet remarkably long, over 600 metres."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the dam is on the River Amarguillo [S3]; the dam is in ruins [S1]; it is a Roman buttress dam [S1]; it dates to the 3rd or 4th century AD [S2]; it is less than 5 metres high [S4]; it is remarkably long, over 600 metres [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-056 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Consuegra Dam is a ruined Roman buttress dam (a dam) [SUPPORTED: https://en.wikipedia.org/wiki/Consuegra_Dam]; It lies in Spain [SUPPORTED: https://en.wikipedia.org/wiki/Consuegra_Dam]; It is on the River Amarguillo [SUPPORTED: https://en.wikipedia.org/wiki/Consuegra_Dam]; It dates to the 3rd or 4th century AD [SUPPORTED: https://en.wikipedia.org/wiki/Consuegra_Dam]; It is less than 5 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Consuegra_Dam]; It is remarkably long, over 600 metres [SUPPORTED: https://en.wikipedia.org/wiki/Consuegra_Dam]"}]'::jsonb),
    ('9fe64aa7-1b1a-4074-b6c2-f2d236938ab4'::uuid, 'card_description', 'The fort was discovered in 1894 under the direction of Heinrich Jacobi, the local section commissioner of the Imperial Limes Commission, and examined in two excavation campaigns in 1894 and 1901.', 'Am Forsthofweg, a Roman fortlet on the Limes, is an almost square earthwork whose only gate faced north. Inside, a wooden construction of around 45 square meters was found, its use unknown.', 'teaser-card-s024:9fe64aa7-1b1a-4074-b6c2-f2d236938ab4:card_description', 'teaser-card-s024 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'a69ac0a1e53bfdacd5c31c18f8f332da217bd8c06062633b4148a7df45cbb74e|9b5cfb945f9de436abec4f9db4ba3bf5b3ca8a42104e30279ba6f425583dcf01|9b5cfb945f9de436abec4f9db4ba3bf5b3ca8a42104e30279ba6f425583dcf01', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Am Forsthofweg, a Roman fortlet on the Limes, is an almost square earthwork whose only gate faced north. Inside, a wooden construction of around 45 square meters was found, its use unknown."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Am Forsthofweg is a Roman fortlet [S1, S5]; it lies on the Limes [S1]; it is an almost square earthwork [S5]; it had only one gate [S7]; the gate faced north [S7]; a wooden construction was found inside [S8]; the wooden construction covered around 45 square meters [S8]; the function of the wooden construction is unknown [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-056 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Am Forsthofweg is a fortlet (small fort), a military site [SUPPORTED: https://en.wikipedia.org/wiki/Am_Forsthofweg]; It is Roman [SUPPORTED: https://en.wikipedia.org/wiki/Am_Forsthofweg]; It lies on the Limes [SUPPORTED: https://en.wikipedia.org/wiki/Am_Forsthofweg]; It is an earthwork [SUPPORTED: https://en.wikipedia.org/wiki/Am_Forsthofweg]; The earthwork is almost square [SUPPORTED: https://en.wikipedia.org/wiki/Am_Forsthofweg]; It had only one gate [SUPPORTED: https://en.wikipedia.org/wiki/Am_Forsthofweg]; The only gate faced north [SUPPORTED: https://en.wikipedia.org/wiki/Am_Forsthofweg]; A wooden construction was found inside the fortlet [SUPPORTED: https://en.wikipedia.org/wiki/Am_Forsthofweg]; The wooden construction covered around 45 square meters [SUPPORTED: https://en.wikipedia.org/wiki/Am_Forsthofweg]; The use (function) of the wooden construction is unknown [SUPPORTED: https://en.wikipedia.org/wiki/Am_Forsthofweg]"}]'::jsonb),
    ('a003bdc8-30b5-4bcf-b594-e8da82583455'::uuid, 'card_description', 'A Sabaean temple from the 7th century BC dedicated to the moon god Almaqah. Local tradition calls it the throne of the Queen of Sheba.', 'In pre-Islamic Yemen, Mahram Bilqis was the most important site of pilgrimage, centered around the god Almaqah. Its oldest inscription tells of building its massive enclosure.', 'teaser-card-s024:a003bdc8-30b5-4bcf-b594-e8da82583455:card_description', 'teaser-card-s024 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', '38eae20e83e039af95c63802d7fbf18cab9c63c11ac55a8c6daab57c06418dc6|e39bf05d90cb3020f380fc7853142247c7dce4c18c6ccbb3e2f78f3a1de2d157|e39bf05d90cb3020f380fc7853142247c7dce4c18c6ccbb3e2f78f3a1de2d157', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In pre-Islamic Yemen, Mahram Bilqis was the most important site of pilgrimage, centered around the god Almaqah. Its oldest inscription tells of building its massive enclosure."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the site is in pre-Islamic Yemen [S2]; it was the most important site of pilgrimage there [S2]; the pilgrimage was centered around the god Almaqah [S2]; its oldest inscription refers to the building of its massive enclosure [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify2-005 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Mahram Bilqis (Awwam Temple) is a temple near Marib, Yemen [SUPPORTED: https://en.wikipedia.org/wiki/Mahram_Bilqis]; It was a temple of the god Almaqah [SUPPORTED: https://en.wikipedia.org/wiki/Mahram_Bilqis]; It was the most important site of pilgrimage in pre-Islamic Yemen [SUPPORTED: https://en.wikipedia.org/wiki/Mahram_Bilqis]; The pilgrimage was centered around the god Almaqah [SUPPORTED: https://en.wikipedia.org/wiki/Mahram_Bilqis]; Its oldest inscription refers to building the temple''s enclosure [SUPPORTED: https://en.wikipedia.org/wiki/Mahram_Bilqis]; The enclosure is massive [SUPPORTED: https://en.wikipedia.org/wiki/Mahram_Bilqis]"}]'::jsonb),
    ('a0736505-9ca5-4361-bc0a-f0a47b6fed7e'::uuid, 'card_description', 'A Roman fish farm from 146 BC with a connecting aqueduct carved into coastal rock. Romans engineered saltwater ponds to breed fish on an industrial scale.', 'East of Santa Eulària des Riu on Ibiza, S''Argamassa Roman Fish Farm keeps remains of rectangular tanks where garum once fermented, before amphoras carried it to all parts of the empire.', 'teaser-card-s024:a0736505-9ca5-4361-bc0a-f0a47b6fed7e:card_description', 'teaser-card-s024 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '625114ee02af0efe4f96b10fea1cd5c7e0f44299e8d3aed0a532c8704137139c|001370ac3840f4ef1a248de849ff97be4931fd33504bd696d18abda2e83a3ebe|001370ac3840f4ef1a248de849ff97be4931fd33504bd696d18abda2e83a3ebe', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "East of Santa Eulària des Riu on Ibiza, S''Argamassa Roman Fish Farm keeps remains of rectangular tanks where garum once fermented, before amphoras carried it to all parts of the empire."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the site lies east of Santa Eulària des Riu on Ibiza [S1]; it is a Roman fish farm [S1, S2]; it keeps remains of rectangular structures that were once the fermenting tanks for garum [S4]; the garum sauce was packed into amphoras [S5]; the garum was exported to all parts of the empire [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify2-005 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "S''Argamassa Roman Fish Farm is on the island of Ibiza, Spain [SUPPORTED: https://en.wikipedia.org/wiki/S%27Argamassa_Roman_Fish_Farm]; It lies east of Santa Eularia des Riu [SUPPORTED: https://en.wikipedia.org/wiki/S%27Argamassa_Roman_Fish_Farm]; Remains of rectangular structures survive at the aqueduct''s end near the shoreline [SUPPORTED: https://en.wikipedia.org/wiki/S%27Argamassa_Roman_Fish_Farm]; The tanks were fermenting tanks for garum [SUPPORTED: https://en.wikipedia.org/wiki/S%27Argamassa_Roman_Fish_Farm]; The garum was packed in amphoras [SUPPORTED: https://en.wikipedia.org/wiki/S%27Argamassa_Roman_Fish_Farm]; It was exported to all parts of the empire [SUPPORTED: https://en.wikipedia.org/wiki/S%27Argamassa_Roman_Fish_Farm]"}]'::jsonb),
    ('a0c839b2-5efa-409c-852a-dcaf88507e64'::uuid, 'card_description', 'A Roman villa near the road from Lisbon to Braga, occupied 1st–5th century AD. Its octagonal peristyle design is architecturally unique in the region.', 'Near the Roman road from Olisipo to Bracara Augusta, digging begun in 1984 laid bare the Roman Villa of Rabaçal: an octagonal peristyle at its heart, the rooms set symmetrically around it.', 'teaser-card-s024:a0c839b2-5efa-409c-852a-dcaf88507e64:card_description', 'teaser-card-s024 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'c949c37cf171005f9935f428fcedd7a25a5f0480ab93b58e411d568cf27776f6|d7a0b3733baa99f4fc87ab61ee23298621c422af186b3c0efb80dd3d313e5147|d7a0b3733baa99f4fc87ab61ee23298621c422af186b3c0efb80dd3d313e5147', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Near the Roman road from Olisipo to Bracara Augusta, digging begun in 1984 laid bare the Roman Villa of Rabaçal: an octagonal peristyle at its heart, the rooms set symmetrically around it."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the villa lies near the Roman road from Olisipo to Bracara Augusta [S1]; excavations began in 1984 [S2]; the excavations exposed the villa''s layout [S2]; an octagonal peristyle is at the villa''s center [S2]; the other rooms are grouped symmetrically around it [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-057 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Rabaçal is a Roman villa in Portugal (near Penela), located near the Roman road from Olisipo to Bracara Augusta [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Raba%C3%A7al]; The road runs from Olisipo to Bracara Augusta [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Raba%C3%A7al]; Excavations begun in 1984 laid bare the villa [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Raba%C3%A7al]; An octagonal peristyle is at the villa''s centre [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Raba%C3%A7al]; The other rooms are grouped symmetrically around the peristyle [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Raba%C3%A7al]"}]'::jsonb),
    ('a1435e3d-4c9d-410e-992e-842f24dfba16'::uuid, 'card_description', 'Priddy Circles are a linear arrangement of four circular earthwork enclosures near the village of Priddy on the Mendip Hills in Somerset.', 'On the Mendip Hills lie the Priddy Circles, four earthwork rings 185 to 194 m across, probable Neolithic ritual monuments. Three form a nearly straight line; the fourth strays to the north.', 'teaser-card-s024:a1435e3d-4c9d-410e-992e-842f24dfba16:card_description', 'teaser-card-s024 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'ab7025a4e873e9d1af09b2f2000cebae6520ffab35be150e76a3bf30c5cfcb6f|d19e4ea53d861ec6845a9039ac83e4f5efd177ad883b855d5573da2694f9cc49|d19e4ea53d861ec6845a9039ac83e4f5efd177ad883b855d5573da2694f9cc49', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On the Mendip Hills lie the Priddy Circles, four earthwork rings 185 to 194 m across, probable Neolithic ritual monuments. Three form a nearly straight line; the fourth strays to the north."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Priddy Circles lie on the Mendip Hills [S1]; there are four earthwork rings [S1]; the rings are 185 to 194 m in diameter [S3]; they are probable Neolithic ritual monuments [S2]; three of them form a nearly straight line [S4]; the fourth lies to the north, out of line with the others [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-057 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Priddy Circles are four circular earthwork enclosures on the Mendip Hills, England [SUPPORTED: https://en.wikipedia.org/wiki/Priddy_Circles]; The circles lie on the Mendip Hills [SUPPORTED: https://en.wikipedia.org/wiki/Priddy_Circles]; There are four enclosures (rings) [SUPPORTED: https://en.wikipedia.org/wiki/Priddy_Circles]; The enclosures range from 185 to 194 m in diameter [SUPPORTED: https://en.wikipedia.org/wiki/Priddy_Circles]; They are probable Neolithic ritual monuments [SUPPORTED: https://en.wikipedia.org/wiki/Priddy_Circles]; Three of the circles form a nearly straight line while the fourth lies to the north, out of line [SUPPORTED: https://en.wikipedia.org/wiki/Priddy_Circles]"}]'::jsonb),
    ('a228ae71-4a7e-4fb5-b773-cee87ffc946b'::uuid, 'card_description', 'A 4th-century Roman triumphal arch that once had four massive arched openings. Only one arch survives, standing alone as a gateway to nowhere.', 'At Carnuntum stands the Heidentor, the Pagans'' Gate, ruin of a Roman triumphal arch, each facade likely 14.5 metres wide. A central plinth probably held a statue of a god or an emperor.', 'teaser-card-s024:a228ae71-4a7e-4fb5-b773-cee87ffc946b:card_description', 'teaser-card-s024 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', 'f80a64daf56a4af98d9c0f7cc11cd956a4dd5ac38dc8a6504cf1527c4395f49a|f0f06ca044c8b182eb6537242b0aefbd150b6d5f9b5bfa4e196e57fdbd20b86d|f0f06ca044c8b182eb6537242b0aefbd150b6d5f9b5bfa4e196e57fdbd20b86d', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "At Carnuntum stands the Heidentor, the Pagans'' Gate, ruin of a Roman triumphal arch, each facade likely 14.5 metres wide. A central plinth probably held a statue of a god or an emperor."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Heidentor stands at Carnuntum [S1]; it is also called the Pagans'' Gate [S1]; it is the ruin of a Roman triumphal arch [S1]; each facade was likely 14.5 metres wide [S2]; a central plinth probably held a statue of a god or an emperor [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-057 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Heidentor (Pagans'' Gate) is the ruin of a Roman triumphal arch at Carnuntum, Austria [SUPPORTED: https://en.wikipedia.org/wiki/Heidentor]; Heidentor means Pagans'' Gate [SUPPORTED: https://en.wikipedia.org/wiki/Heidentor]; The monument is at Carnuntum [SUPPORTED: https://en.wikipedia.org/wiki/Heidentor]; Each facade was likely 14.5 metres wide [SUPPORTED: https://en.wikipedia.org/wiki/Heidentor]; A central plinth probably held a statue of a god or an emperor [SUPPORTED: https://en.wikipedia.org/wiki/Heidentor]"}]'::jsonb),
    ('a2720609-acca-47c5-b778-15568e68a67e'::uuid, 'card_description', 'The type site of the Aurignacian culture, the earliest modern human tradition in Europe. Artifacts here defined an entire 19,000-year period (43,000–24,000 BC).', 'Finely cut flints and worked reindeer antlers came out of the Cave of Aurignac, type site of the Aurignacian, the earliest known culture attributed to modern humans in western Eurasia.', 'teaser-card-s024:a2720609-acca-47c5-b778-15568e68a67e:card_description', 'teaser-card-s024 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', 'c0a7983c81f7152dfbf34ab2c2a7ecb72838a95d3d588ec018770953236aa11a|fefa5b22549e4d0e4da3f133f01f9810fc4853dac22965b0bde72a2766e9bf2f|fefa5b22549e4d0e4da3f133f01f9810fc4853dac22965b0bde72a2766e9bf2f', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Finely cut flints and worked reindeer antlers came out of the Cave of Aurignac, type site of the Aurignacian, the earliest known culture attributed to modern humans in western Eurasia."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "finely cut flints came out of the Cave of Aurignac [S5]; worked reindeer antlers came out of the Cave of Aurignac [S5]; the Cave of Aurignac is the type site of the Aurignacian [S2]; the Aurignacian is the earliest known culture attributed to modern humans in western Eurasia [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-057 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Cave of Aurignac is the type site of the Aurignacian [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Aurignac]; The Aurignacian is the earliest known culture attributed to modern humans in western Eurasia [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Aurignac]; Finely cut flints and worked reindeer antlers came out of the cave [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Aurignac]; Worked reindeer antlers came out of the cave [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Aurignac]"}]'::jsonb),
    ('a2b571fa-4aa3-4c23-b5f0-13c5552ce870'::uuid, 'card_description', 'Royal estate of Inca emperor Huayna Capac, built 1464–1525 AD in the Sacred Valley at 2,910 metres. Such estates concentrated wealth in the emperor''s bloodline and served as fortified country palaces.', 'Fitted stonework, gatehouses and the foundation of a great hall mark Quispiguanca, royal estate of the Inca emperor Huayna Capac, taken by Francisco Pizarro as his encomienda in the 1530s.', 'teaser-card-s024:a2b571fa-4aa3-4c23-b5f0-13c5552ce870:card_description', 'teaser-card-s024 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'fb7f73fa4a6d1f9d6bc28e64dd635d5be41ff72425c1a3263c75c500624e445f|024d40a1ad7310c0faed13c55907d30b68803eb316278f0ffcf2c0c33c2a1642|024d40a1ad7310c0faed13c55907d30b68803eb316278f0ffcf2c0c33c2a1642', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Fitted stonework, gatehouses and the foundation of a great hall mark Quispiguanca, royal estate of the Inca emperor Huayna Capac, taken by Francisco Pizarro as his encomienda in the 1530s."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the site has fitted stonework [S5]; the site has gatehouses [S4]; the site has the foundation of a great hall [S7]; Quispiguanca was a royal estate [S1]; the estate belonged to the Inca emperor Huayna Capac [S1]; Francisco Pizarro took the estate as his encomienda [S8]; this happened in the 1530s [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-057 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Quispiguanca is a royal estate of the Inca emperor Huayna Capac (Peru) [SUPPORTED: https://en.wikipedia.org/wiki/Quispiguanca]; The estate belonged to Huayna Capac [SUPPORTED: https://en.wikipedia.org/wiki/Quispiguanca]; The construction is of fitted stonework [SUPPORTED: https://en.wikipedia.org/wiki/Quispiguanca]; The site has gatehouses [SUPPORTED: https://en.wikipedia.org/wiki/Quispiguanca]; The site has the foundation of a great hall [SUPPORTED: https://en.wikipedia.org/wiki/Quispiguanca]; Francisco Pizarro took the estate as his encomienda in the 1530s [SUPPORTED: https://en.wikipedia.org/wiki/Quispiguanca]; The encomienda dates to the 1530s [SUPPORTED: https://en.wikipedia.org/wiki/Quispiguanca]"}]'::jsonb),
    ('a3a38d98-16fc-464f-bbeb-c027813ef202'::uuid, 'card_description', 'Scordisci Celts settled here in the 3rd century BC; Rome seized it by the 1st century BC and renamed it Acumincum — meaning "point" — for its bluff above the Pannonian Limes.', 'Celtic Scordisci lived in this area in the 3rd century BC. Here lay Acumincum, a Roman settlement in the town of Stari Slankamen, where sculptures of Jupiter Dolichenus have been found.', 'teaser-card-s024:a3a38d98-16fc-464f-bbeb-c027813ef202:card_description', 'teaser-card-s024 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '614c2cf1e144079d02463147a831a70f154fea9bd667f667727585b77e40295e|6f17a3440b4a583f4abca3b12b3012bc182ba03964e78f99b5d5e7f29bb211e5|6f17a3440b4a583f4abca3b12b3012bc182ba03964e78f99b5d5e7f29bb211e5', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Celtic Scordisci lived in this area in the 3rd century BC. Here lay Acumincum, a Roman settlement in the town of Stari Slankamen, where sculptures of Jupiter Dolichenus have been found."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Celtic Scordisci lived in the area [S2]; they lived there in the 3rd century BC [S2]; Acumincum was a Roman settlement [S1]; it lay in the town of Stari Slankamen [S1]; sculptures of Jupiter Dolichenus have been found there [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-058 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Acumincum was a Roman settlement [SUPPORTED: https://en.wikipedia.org/wiki/Acumincum]; It was located in the town of Stari Slankamen [SUPPORTED: https://en.wikipedia.org/wiki/Acumincum]; The area was inhabited by the Celtic Scordisci [SUPPORTED: https://en.wikipedia.org/wiki/Acumincum]; The Scordisci lived there in the 3rd century BC [SUPPORTED: https://en.wikipedia.org/wiki/Acumincum]; Sculptures of Jupiter Dolichenus have been found there [SUPPORTED: https://en.wikipedia.org/wiki/Acumincum]; The site is in Serbia [SUPPORTED: https://en.wikipedia.org/wiki/Acumincum]"}]'::jsonb),
    ('a4955f7b-3996-4477-9540-891364da6c71'::uuid, 'card_description', 'A 137-km Roman-era ditch running along the western Fens edge. Whether it functioned as a canal, a drainage channel, or a territorial boundary remains actively debated among archaeologists.', 'Along the western edge of the Fens runs the Car Dyke, a ditch of over 57 miles generally accepted as Roman, cutting north to south where all the natural drainage flows west to east.', 'teaser-card-s024:a4955f7b-3996-4477-9540-891364da6c71:card_description', 'teaser-card-s024 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', 'b2d739de92166b4ac3e43ac3d49cc30c922e1064b684864c0650652a2019c382|4b5c68d87bfb9f91b24f323bb6252f4692baf936585390f443440e32c1cb1f1c|4b5c68d87bfb9f91b24f323bb6252f4692baf936585390f443440e32c1cb1f1c', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Along the western edge of the Fens runs the Car Dyke, a ditch of over 57 miles generally accepted as Roman, cutting north to south where all the natural drainage flows west to east."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Car Dyke runs along the western edge of the Fens [S1]; it is a ditch [S1]; it is over 57 miles long [S1]; it is generally accepted as Roman [S2]; it runs north to south [S6]; all the natural drainage of the area flows west to east [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-058 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Car Dyke is a ditch [SUPPORTED: https://en.wikipedia.org/wiki/Car_Dyke]; It runs along the western edge of the Fens [SUPPORTED: https://en.wikipedia.org/wiki/Car_Dyke]; It is over 57 miles long [SUPPORTED: https://en.wikipedia.org/wiki/Car_Dyke]; It is generally accepted as Roman [SUPPORTED: https://en.wikipedia.org/wiki/Car_Dyke]; It runs north to south [SUPPORTED: https://en.wikipedia.org/wiki/Car_Dyke]; All natural drainage in the area flows west to east [SUPPORTED: https://en.wikipedia.org/wiki/Car_Dyke]"}]'::jsonb),
    ('a4990269-42fc-45f8-9849-905dbf3f68fb'::uuid, 'card_description', 'The Anju Castle is a military fortress built during the Goguryeo kingdom, later rebuilt during Joseon era.', 'On the shore of the Chongchon River, the Goguryeo walls of Anju Castle''s inner fort ran 6500 metres along the Kadu range, joined by a Joseon outer fort and a new fort of the 17th century.', 'teaser-card-s024:a4990269-42fc-45f8-9849-905dbf3f68fb:card_description', 'teaser-card-s024 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '332c75f487dcc1e4555d2623df6c18bfa5c14d3f4199f899f7b2d8900fbcba04|4dd0e556f4ee7cde261939ac3285ba879fdf9677e27f7cd4f03d4e5c8e9bae95|4dd0e556f4ee7cde261939ac3285ba879fdf9677e27f7cd4f03d4e5c8e9bae95', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On the shore of the Chongchon River, the Goguryeo walls of Anju Castle''s inner fort ran 6500 metres along the Kadu range, joined by a Joseon outer fort and a new fort of the 17th century."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the inner fort''s walls stand on the shore of the Chongchon River [S4]; the inner fort''s walls date from the Goguryeo period [S4]; the inner fort''s walls run along the Kadu range [S4]; these walls are 6500 metres long [S5]; Anju Castle has an outer fort built in the Joseon period [S6]; Anju Castle has a new fort built in the 17th century [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-058 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Anju Castle is a fortress (Goguryeo origin, North Korea) [SUPPORTED: https://en.wikipedia.org/wiki/Anju_Castle]; The inner fort has Goguryeo walls [SUPPORTED: https://en.wikipedia.org/wiki/Anju_Castle]; The walls run along the Kadu range [SUPPORTED: https://en.wikipedia.org/wiki/Anju_Castle]; The site is on the shore of the Chongchon River [SUPPORTED: https://en.wikipedia.org/wiki/Anju_Castle]; The inner fort walls were 6500 metres long [SUPPORTED: https://en.wikipedia.org/wiki/Anju_Castle]; The outer fort is of the Joseon period [SUPPORTED: https://en.wikipedia.org/wiki/Anju_Castle]; A new fort exists [SUPPORTED: https://en.wikipedia.org/wiki/Anju_Castle]; The new fort was built in the 17th century [SUPPORTED: https://en.wikipedia.org/wiki/Anju_Castle]"}]'::jsonb),
    ('a4f216bd-ef7d-4764-aa03-c88b3d5a588e'::uuid, 'card_description', 'Researchers found thousands of artefacts and bone fragments, which enabled them to date the shelter''s occupation to a number of periods between 49,000 and 10,000 years ago.', 'In a gorge of the northern Flinders Ranges, Warratyi holds the earliest evidence in Australia of bone and stone-axe technology and the use of ochre, in Adnyamathanha ancestral lands.', 'teaser-card-s024:a4f216bd-ef7d-4764-aa03-c88b3d5a588e:card_description', 'teaser-card-s024 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '9ed3f65ab3a3eec15393d5f8ecc37a6759f7b26680ec6fdcc1b8750d2b18cd01|7d9700417afc4489d3928951094c6cdb9e4b5edf2795e975fd1964f113a42eb9|7d9700417afc4489d3928951094c6cdb9e4b5edf2795e975fd1964f113a42eb9', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In a gorge of the northern Flinders Ranges, Warratyi holds the earliest evidence in Australia of bone and stone-axe technology and the use of ochre, in Adnyamathanha ancestral lands."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Warratyi lies in a gorge [S6]; the gorge is in the northern Flinders Ranges [S6]; it holds the earliest evidence in Australia of bone technology [S4]; it holds the earliest evidence in Australia of stone-axe technology [S4]; it holds the earliest evidence in Australia of the use of ochre [S4]; it is in Adnyamathanha ancestral lands [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify2-006 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Warratyi is an archaeological site (rock shelter) in the Flinders Ranges, Australia [SUPPORTED: https://en.wikipedia.org/wiki/Warratyi]; Warratyi lies in a gorge in the northern Flinders Ranges [SUPPORTED: https://en.wikipedia.org/wiki/Warratyi]; Warratyi holds the earliest evidence in Australia of bone technology [SUPPORTED: https://en.wikipedia.org/wiki/Warratyi]; Warratyi holds the earliest evidence in Australia of stone-axe technology [SUPPORTED: https://en.wikipedia.org/wiki/Warratyi]; Warratyi holds the earliest evidence in Australia of the use of ochre [SUPPORTED: https://en.wikipedia.org/wiki/Warratyi]; The site is in Adnyamathanha ancestral lands [SUPPORTED: https://en.wikipedia.org/wiki/Warratyi]"}]'::jsonb),
    ('a61f0c60-94d8-43c4-9c2f-e30ffff8da13'::uuid, 'card_description', 'Iron Age plateau fort on a chalk ridge in Hampshire, enclosing 1.7 hectares with a single bank and ditch. Largely destroyed and overgrown, the southern ramparts preserve the best evidence.', 'On a chalk ridge at 220 metres, the overgrown earthworks of Bevisbury, an Iron Age plateau fort, are cut in two by a Roman road running between Winchester and Mildenhall.', 'teaser-card-s024:a61f0c60-94d8-43c4-9c2f-e30ffff8da13:card_description', 'teaser-card-s024 (teaser-card): teaser card, 170 characters, checked PASS, web-verified VERIFIED', 'c2e8be58e2815ab0aa652ba03b1fc8ac68bda7f09839a42340e9a0499ed2f205|a7533e11f2e50ce16bbebaa166633216d4d7659eac8cbcb1f9cff5373ac10ebb|a7533e11f2e50ce16bbebaa166633216d4d7659eac8cbcb1f9cff5373ac10ebb', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On a chalk ridge at 220 metres, the overgrown earthworks of Bevisbury, an Iron Age plateau fort, are cut in two by a Roman road running between Winchester and Mildenhall."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Bevisbury lies on a chalk ridge [S2]; it lies at a height of 220 metres [S7]; its earthworks are overgrown [S3]; it is an Iron Age plateau fort [S1]; a Roman road cuts the site in two [S6]; the road runs between Winchester and Mildenhall [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-058 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Bevisbury is an Iron Age plateau fort [SUPPORTED: https://en.wikipedia.org/wiki/Bevisbury]; It lies on a chalk ridge [SUPPORTED: https://en.wikipedia.org/wiki/Bevisbury]; It lies at 220 metres [SUPPORTED: https://en.wikipedia.org/wiki/Bevisbury]; Its earthworks are overgrown [SUPPORTED: https://en.wikipedia.org/wiki/Bevisbury]; A Roman road cuts the site in two [SUPPORTED: https://en.wikipedia.org/wiki/Bevisbury]; The Roman road runs between Winchester and Mildenhall [SUPPORTED: https://en.wikipedia.org/wiki/Bevisbury]; The site is in England [SUPPORTED: https://en.wikipedia.org/wiki/Bevisbury]"}]'::jsonb),
    ('a68e0f4e-3d6a-4e33-a768-b7fad0b07a8e'::uuid, 'card_description', 'A Bronze Age site in the Argolid with a cemetery that yielded the Dendra Panoply — a complete suit of bronze armor from around 1450 BC, the oldest complete bronze armor suit in Europe.', 'Approximately 6 kilometres from Argos, Dendra holds a tholos tomb named the Royal Tomb, three tumuli and sixteen chamber tombs, one of the richest cemeteries known from the Mycenaean period.', 'teaser-card-s024:a68e0f4e-3d6a-4e33-a768-b7fad0b07a8e:card_description', 'teaser-card-s024 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', '9bd4c8b83f2b66fb1289ae737a33fc5503536774c629b5129ba4106565f14551|98a19667824e2115ec4f519d4aeed5308a432af679fd59c236860fec5de13d03|98a19667824e2115ec4f519d4aeed5308a432af679fd59c236860fec5de13d03', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Approximately 6 kilometres from Argos, Dendra holds a tholos tomb named the Royal Tomb, three tumuli and sixteen chamber tombs, one of the richest cemeteries known from the Mycenaean period."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Dendra lies approximately 6 kilometres from Argos [S2]; the site has a tholos tomb [S4]; the tholos tomb is named the Royal Tomb [S5]; the site has three tumuli [S4]; the site has sixteen chamber tombs [S4]; it is one of the richest cemeteries known from the Mycenaean period [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Dendra is a prehistoric archaeological site with a Late Bronze Age cemetery (a tomb/cemetery site), in the Argolid, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Dendra]; Dendra is approximately 6 kilometres from Argos [SUPPORTED: https://en.wikipedia.org/wiki/Dendra]; Dendra has a tholos tomb named the Royal Tomb [SUPPORTED: https://en.wikipedia.org/wiki/Dendra]; Dendra has three tumuli [SUPPORTED: https://en.wikipedia.org/wiki/Dendra]; Dendra has sixteen chamber tombs [SUPPORTED: https://en.wikipedia.org/wiki/Dendra]; The Dendra cemetery is one of the richest known from the Mycenaean period [SUPPORTED: https://en.wikipedia.org/wiki/Dendra]"}]'::jsonb),
    ('a694497b-30ab-4283-be76-d1570d7c90ad'::uuid, 'card_description', 'The settlement at Sesklo gives its name to the earliest known Neolithic culture of Europe.', 'Sesklo gives its name to the earliest known Neolithic culture of Europe. At its peak, circa 5000 BC, the settlement spread over approximately 20 hectares, with about 500 to 800 houses.', 'teaser-card-s024:a694497b-30ab-4283-be76-d1570d7c90ad:card_description', 'teaser-card-s024 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '26ac2cfd4a0167731aecb8d87cb8403a756a5bf497200550d07b996531e7b3ce|20aa8f083f889e19623214b463612f86ea489806d6c0a2bd0cf821e86b9e5f97|20aa8f083f889e19623214b463612f86ea489806d6c0a2bd0cf821e86b9e5f97', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Sesklo gives its name to the earliest known Neolithic culture of Europe. At its peak, circa 5000 BC, the settlement spread over approximately 20 hectares, with about 500 to 800 houses."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Sesklo gives its name to the earliest known Neolithic culture of Europe [S2]; the settlement''s peak was around 5000 BC [S6]; at its peak it covered approximately 20 hectares [S6]; at its peak it had about 500 to 800 houses [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Sesklo is a Neolithic settlement near Volos, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Sesklo]; Sesklo gives its name to the earliest known Neolithic culture of Europe [SUPPORTED: https://en.wikipedia.org/wiki/Sesklo]; At its peak, circa 5000 BC, the settlement covered approximately 20 hectares [SUPPORTED: https://en.wikipedia.org/wiki/Sesklo]; The settlement had about 500 to 800 houses [SUPPORTED: https://en.wikipedia.org/wiki/Sesklo]"}]'::jsonb),
    ('a791798d-8ed0-4134-bd0d-de1deaef99a1'::uuid, 'card_description', 'The mythic port where Jason launched the Argo with fifty demigods to seek the Golden Fleece. The city''s Bronze Age roots run deep beneath modern settlement.', 'In Greek myth, Pelias seized the throne of Iolcus from Aeson and sent Jason and his Argonauts to look for the Golden Fleece. Homer names it in the Catalogue of Ships in the Iliad.', 'teaser-card-s024:a791798d-8ed0-4134-bd0d-de1deaef99a1:card_description', 'teaser-card-s024 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '279f2d50bc59788b718483356d70a24fb5fc59f7aad3c1098975b99629008f4c|53e58ecc3778592c5881188b02726a50c3ea4972375551e00b2e54a202a13695|53e58ecc3778592c5881188b02726a50c3ea4972375551e00b2e54a202a13695', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In Greek myth, Pelias seized the throne of Iolcus from Aeson and sent Jason and his Argonauts to look for the Golden Fleece. Homer names it in the Catalogue of Ships in the Iliad."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "this is told in Greek myth [S1]; Pelias seized the throne of Iolcus from Aeson [S1]; Pelias sent Jason and his Argonauts to look for the Golden Fleece [S2]; Homer names Iolcus in the Catalogue of Ships in the Iliad [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Iolcus is an ancient city in Magnesia, Thessaly, Greece, known from Greek myth [SUPPORTED: https://en.wikipedia.org/wiki/Iolcus]; In Greek myth Pelias seized (usurped) the throne of Iolcus from Aeson [SUPPORTED: https://en.wikipedia.org/wiki/Iolcus]; Pelias sent Jason and his Argonauts to look for the Golden Fleece [SUPPORTED: https://en.wikipedia.org/wiki/Iolcus]; Homer names Iolcus in the Catalogue of Ships in the Iliad [SUPPORTED: https://en.wikipedia.org/wiki/Iolcus]"}]'::jsonb),
    ('a80e7611-46f8-4fd6-a74b-0b5e29defa6e'::uuid, 'card_description', 'A cave complex containing the oldest known human remains in Europe, dating back over 800,000 years. A new human species, Homo antecessor, was defined from bones found here.', 'Digs at the Archaeological Site of Atapuerca yielded more than 5,500 human remains at least 350,000 years old, from 28 individuals of Homo heidelbergensis, and a hand axe called Excalibur.', 'teaser-card-s024:a80e7611-46f8-4fd6-a74b-0b5e29defa6e:card_description', 'teaser-card-s024 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'f43df5648a9350bd38530e3dc1401adb66df003af2b2fef85df008c2217cbbaa|93c143c64870be197790ab8451b46728348cf8c023ab42191ee43bca78963b26|93c143c64870be197790ab8451b46728348cf8c023ab42191ee43bca78963b26', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Digs at the Archaeological Site of Atapuerca yielded more than 5,500 human remains at least 350,000 years old, from 28 individuals of Homo heidelbergensis, and a hand axe called Excalibur."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "excavations at the site yielded more than 5,500 human remains [S4]; these remains are at least 350,000 years old [S4]; they come from 28 individuals [S4]; the individuals are Homo heidelbergensis [S4]; a hand axe called Excalibur was found there [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Archaeological Site of Atapuerca, in Burgos province, northern Spain, is a site of early human occupation (cave complex with fossil deposits) [SUPPORTED: https://en.wikipedia.org/wiki/Archaeological_site_of_Atapuerca]; Excavations yielded more than 5,500 human remains [SUPPORTED: https://en.wikipedia.org/wiki/Archaeological_site_of_Atapuerca]; The remains are at least 350,000 years old [SUPPORTED: https://en.wikipedia.org/wiki/Archaeological_site_of_Atapuerca]; The remains represent 28 individuals of Homo heidelbergensis [SUPPORTED: https://en.wikipedia.org/wiki/Archaeological_site_of_Atapuerca]; A hand axe called Excalibur was found among the associated finds [SUPPORTED: https://en.wikipedia.org/wiki/Archaeological_site_of_Atapuerca]"}]'::jsonb),
    ('a86f1885-cf64-4dfc-bbec-b388a3ae2ebf'::uuid, 'card_description', 'A Roman courtyard villa of 14 rooms with mosaics, underfloor heating, and painted walls. Pottery dates it mainly to the late 4th century AD.', 'Totternhoe Roman Villa was a courtyard house of at least 14 rooms, with mosaics, hypocausts and painted wall plaster. Saxon potsherds suggest someone lived here after it was abandoned.', 'teaser-card-s024:a86f1885-cf64-4dfc-bbec-b388a3ae2ebf:card_description', 'teaser-card-s024 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', 'df5fc8645ab08b85364b641a806499b93a2dbf9793c18efdff97c71d4e0b39ff|d36e0be8896648cdba9103599c3012a123d9c90b1d70a3268405fcaf30bb1106|d36e0be8896648cdba9103599c3012a123d9c90b1d70a3268405fcaf30bb1106', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Totternhoe Roman Villa was a courtyard house of at least 14 rooms, with mosaics, hypocausts and painted wall plaster. Saxon potsherds suggest someone lived here after it was abandoned."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Totternhoe Roman Villa was a courtyard house [S3]; it had at least 14 rooms [S3]; it had mosaics [S3]; it had hypocausts [S3]; it had painted wall plaster [S3]; Saxon potsherds were found there [S5]; the potsherds suggest occupation after the villa was abandoned [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Totternhoe Roman villa is a Roman villa at Church Farm, Totternhoe, Bedfordshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Totternhoe_Roman_villa]; It was a courtyard house [SUPPORTED: https://en.wikipedia.org/wiki/Totternhoe_Roman_villa]; It had at least 14 rooms [SUPPORTED: https://en.wikipedia.org/wiki/Totternhoe_Roman_villa]; It had mosaics [SUPPORTED: https://en.wikipedia.org/wiki/Totternhoe_Roman_villa]; It had hypocausts [SUPPORTED: https://en.wikipedia.org/wiki/Totternhoe_Roman_villa]; It had painted wall plaster [SUPPORTED: https://en.wikipedia.org/wiki/Totternhoe_Roman_villa]; Saxon potsherds were found [SUPPORTED: https://en.wikipedia.org/wiki/Totternhoe_Roman_villa]; The Saxon potsherds suggest someone lived here after the villa was abandoned [SUPPORTED: https://en.wikipedia.org/wiki/Totternhoe_Roman_villa]"}]'::jsonb),
    ('a898b46f-484a-4975-a9e6-9a396670eeeb'::uuid, 'card_description', 'A large gritstone boulder from 3300-900 BC on Stanton Moor. It stands alone among Bronze Age barrows and stone circles, likely serving as a landmark or boundary marker.', 'On Stanton Moor, within a low circular dry stone wall, lies the Andle Stone: a gritstone boulder 6m long and 4m high, covered in cup and ring marks, also known as the Twopenny Loaf.', 'teaser-card-s024:a898b46f-484a-4975-a9e6-9a396670eeeb:card_description', 'teaser-card-s024 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '6d174edc804fba5d0129db3e49ebd477727f98e31554cfd3d3daff87334ffe31|b9dafed110050442f8acde73e2b77e3290ac1a3a82a058674fcfc607920656e6|b9dafed110050442f8acde73e2b77e3290ac1a3a82a058674fcfc607920656e6', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On Stanton Moor, within a low circular dry stone wall, lies the Andle Stone: a gritstone boulder 6m long and 4m high, covered in cup and ring marks, also known as the Twopenny Loaf."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Andle Stone lies on Stanton Moor [S1]; it lies within a low, circular dry stone wall [S2]; it is a gritstone boulder [S1]; it is 6m long [S2]; it is 4m high [S2]; it is covered in cup and ring marks [S3]; it is also known as the Twopenny Loaf [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Andle Stone is a large boulder (a standing/natural stone monument). [SUPPORTED: https://en.wikipedia.org/wiki/Andle_Stone]; It is on Stanton Moor (Derbyshire, England). [SUPPORTED: https://en.wikipedia.org/wiki/Andle_Stone]; The boulder is made of gritstone. [SUPPORTED: https://en.wikipedia.org/wiki/Andle_Stone]; The boulder is 6m long. [SUPPORTED: https://en.wikipedia.org/wiki/Andle_Stone]; The boulder is 4m high. [SUPPORTED: https://en.wikipedia.org/wiki/Andle_Stone]; It lies within a low circular dry stone wall. [SUPPORTED: https://en.wikipedia.org/wiki/Andle_Stone]; It is covered in cup and ring marks. [SUPPORTED: https://en.wikipedia.org/wiki/Andle_Stone]; It is also known as the Twopenny Loaf. [SUPPORTED: https://en.wikipedia.org/wiki/Andle_Stone]"}]'::jsonb),
    ('a996a5d6-dd44-441f-9616-b912c06f7f75'::uuid, 'card_description', '200-900 AD Maya city with temple-mounds 8-20 m high, some atop modified hills. Its upper plaza was built on a reshaped ridge 300 m long and 30 m high -- the landscape itself became the architecture.', 'Ian Graham found this ruined Maya city in the 1970s and named it El Pajaral for the numerous birds he met there. At its heart, an enormous staircase 46 metres wide leads to the Main Plaza.', 'teaser-card-s024:a996a5d6-dd44-441f-9616-b912c06f7f75:card_description', 'teaser-card-s024 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '8e6ee599f803748e0dea419d9558515289d34a22668ddc38ab3f94bebcda41aa|b14bf4b37e41d3a983c109041367c34eb8f94fadb68bff75b3c40a34440697b2|b14bf4b37e41d3a983c109041367c34eb8f94fadb68bff75b3c40a34440697b2', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Ian Graham found this ruined Maya city in the 1970s and named it El Pajaral for the numerous birds he met there. At its heart, an enormous staircase 46 metres wide leads to the Main Plaza."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Ian Graham discovered the site [S2]; the discovery was in the 1970s [S2]; it is a ruined Maya city [S1]; Ian Graham named it El Pajaral [S2]; the name refers to the numerous birds he encountered there [S2]; at the heart of the site an enormous staircase leads to the Main Plaza [S5]; the staircase is 46 metres wide [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Pajaral is a ruined Maya city. [SUPPORTED: https://en.wikipedia.org/wiki/Pajaral]; It is in Guatemala. [SUPPORTED: https://en.wikipedia.org/wiki/Pajaral]; Ian Graham found the site. [SUPPORTED: https://en.wikipedia.org/wiki/Pajaral]; He found it in the 1970s. [SUPPORTED: https://en.wikipedia.org/wiki/Pajaral]; He named it El Pajaral. [SUPPORTED: https://en.wikipedia.org/wiki/Pajaral]; The name refers to the numerous birds he met there. [SUPPORTED: https://en.wikipedia.org/wiki/Pajaral]; An enormous staircase 46 metres wide stands at the heart of the site. [SUPPORTED: https://en.wikipedia.org/wiki/Pajaral]; The staircase leads to the Main Plaza. [SUPPORTED: https://en.wikipedia.org/wiki/Pajaral]"}]'::jsonb),
    ('a9a32ee2-bd62-4fe4-8515-0ccdda65a7ee'::uuid, 'card_description', 'A submerged Mesolithic settlement in 11 metres of water, discovered when a lobster was seen tossing worked flint tools from its burrow. Dates to around 6000 BC.', 'In approximately 11 metres of water off the Isle of Wight lies Bouldnor Cliff, a settlement of about 8,000 years ago: burnt flints, mounds of timbers and pits, preserved under silt and mud.', 'teaser-card-s024:a9a32ee2-bd62-4fe4-8515-0ccdda65a7ee:card_description', 'teaser-card-s024 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'd2571f7f0eb1306f30c6b2c18ff860a3cc7c0d036090d000fd40443350dd958c|ed6a4ae9b41d62d211327a9ff8c66b3b626dbd1d600e1b336993c8f7fe918dff|ed6a4ae9b41d62d211327a9ff8c66b3b626dbd1d600e1b336993c8f7fe918dff', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In approximately 11 metres of water off the Isle of Wight lies Bouldnor Cliff, a settlement of about 8,000 years ago: burnt flints, mounds of timbers and pits, preserved under silt and mud."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Bouldnor Cliff lies in approximately 11 metres of water [S2]; it lies off the Isle of Wight [S2]; it was a settlement about 8,000 years ago [S3]; burnt flints were found there [S6]; mounds of timbers were found there [S6]; pits were found there [S6]; the remains are preserved under silt and mud [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Bouldnor Cliff is a settlement site. [SUPPORTED: https://en.wikipedia.org/wiki/Bouldnor_Cliff]; It lies off the Isle of Wight. [SUPPORTED: https://en.wikipedia.org/wiki/Bouldnor_Cliff]; It lies in approximately 11 metres of water. [SUPPORTED: https://en.wikipedia.org/wiki/Bouldnor_Cliff]; The settlement dates to about 8,000 years ago. [SUPPORTED: https://en.wikipedia.org/wiki/Bouldnor_Cliff]; Finds include burnt flints. [SUPPORTED: https://en.wikipedia.org/wiki/Bouldnor_Cliff]; Finds include mounds of timbers. [SUPPORTED: https://en.wikipedia.org/wiki/Bouldnor_Cliff]; Finds include pits. [SUPPORTED: https://en.wikipedia.org/wiki/Bouldnor_Cliff]; The remains were preserved under silt and mud. [SUPPORTED: https://en.wikipedia.org/wiki/Bouldnor_Cliff]"}]'::jsonb),
    ('a9acce8d-1324-434d-913d-519e7c4eb619'::uuid, 'card_description', 'Over 400 m long and 30 m wide, Mérida''s circus held 30,000 spectators for chariot racing from c. 20 BC. Its starting gates and central spine are the most legible of any surviving Roman circus.', 'Chariots raced in the Roman Circus of Mérida, more than 400 m long, with room for up to 30,000 spectators. Its triumph gate, the Porta Triumphalis, survives, as does its spina wall.', 'teaser-card-s024:a9acce8d-1324-434d-913d-519e7c4eb619:card_description', 'teaser-card-s024 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', 'd0c221097cc1faa647e6d92cc721ac7686c999a1ec4f8298b7ac153bbb0d16ed|2795bd93d63617071c5faccbcd0821f067fbe19d31fc7ffcb3728fc60a9f1e19|2795bd93d63617071c5faccbcd0821f067fbe19d31fc7ffcb3728fc60a9f1e19', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Chariots raced in the Roman Circus of Mérida, more than 400 m long, with room for up to 30,000 spectators. Its triumph gate, the Porta Triumphalis, survives, as does its spina wall."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "chariots raced in the Roman Circus of Mérida [S2]; it is more than 400 m long [S3]; it could hold up to 30,000 spectators [S3]; its triumph gate, the Porta Triumphalis, survives [S6]; its spina wall survives [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Roman Circus of Mérida is a Roman circus used for chariot racing (in Mérida, Spain). [SUPPORTED: https://en.wikipedia.org/wiki/Roman_circus_of_M%C3%A9rida]; It is more than 400 m long. [SUPPORTED: https://en.wikipedia.org/wiki/Roman_circus_of_M%C3%A9rida]; It had room for up to 30,000 spectators. [SUPPORTED: https://en.wikipedia.org/wiki/Roman_circus_of_M%C3%A9rida]; Its triumph gate, the Porta Triumphalis, survives. [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Roman_circus_of_M%C3%A9rida]; Its spina wall survives. [SUPPORTED: https://en.wikipedia.org/wiki/Roman_circus_of_M%C3%A9rida]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 100;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s024', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s024'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s024'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 100 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK: nothing may have changed
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s024'
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
-- `_teaser_card_plan` is a CREATE TEMP TABLE, so it lives in this session's `pg_temp_N` schema and
-- `nspname = 'public'` could never match it - the old form of this read was 0 whatever happened.
-- `to_regclass('pg_temp....')` resolves the current session's temp schema and is NULL when the
-- table is gone, so this reads 1 exactly when a leftover exists.
SELECT 'temp table _teaser_card_plan left behind',
       (to_regclass('pg_temp._teaser_card_plan') IS NOT NULL)::int::text
